    [usageError, setUsageError] = useState("");
  const [archived, setArchived] = useState(false),
    [undo, setUndo] = useState<Row | null>(null),
    [deleting, setDeleting] = useState("");
  const [adding, setAdding] = useState(false),
    [newName, setNewName] = useState(""),
    [uploads, setUploads] = useState<Row[]>([]);
  const files = useRef<HTMLInputElement>(null),
    uploadRows = useRef<Row[]>([]);
  useEffect(() => {
    uploadRows.current = uploads;
  }, [uploads]);
  useEffect(
    () => () => uploadRows.current.forEach((u) => URL.revokeObjectURL(u.url)),
    [],
  );
  useEffect(() => {
    if (!detail) return;
    let live = true;
    setUsage([]);
    setUsageError("");
    api(`library/${detail.id}/usage`)
      .then((data) => {
        if (live) setUsage(data.usage);
      })
      .catch((e) => {
        if (live) setUsageError(e.message);
      });
    return () => {
      live = false;
    };
  }, [detail?.id, state.dishes]);
  const allDishes: Row[] = state.dishes;
  const dishes = allDishes
    .filter(
      (d) =>
        !!d.archived_at === archived &&
        (!section || d.category === section) &&
        (!status || dishStatus(d, state.assets) === status) &&
        `${d.name} ${d.description} ${d.category}`
          .toLowerCase()
          .includes(search.toLowerCase()),
    )
    .sort((a, b) =>
      sort === "name"
        ? a.name.localeCompare(b.name)
        : (b.updated_at || b.created_at) - (a.updated_at || a.created_at),
    );
  const filterCount = Number(!!section) + Number(!!status) + Number(archived);
  const clearFilters = () => {
    if (archived) {
      setSelected([]);
      setSelecting(false);
      if (selected.length)
        action.setNotice("Selection cleared when returning to active dishes.");
    }
    setSearch("");
    setSection("");
    setStatus("");
    setSort("recent");
    setArchived(false);
  };
  const currentDish =
    detail && (allDishes.find((d) => d.id === detail.id) || detail);
  const photos = detail ? dishPhotos(detail, state.assets) : [];
  const current =
    photos.find((a) => a.id === chosen) ||
    (currentDish && preferredPhoto(currentDish, state.assets));
  function open(d: Row) {
    action.setNotice("");
    action.setError("");
    setDetail({ ...d, price: d.price / 100, available: !!d.available });
    setChosen(preferredPhoto(d, state.assets)?.id || "");
    setDirty(false);
  }
  function edit(p: Row) {
    action.setNotice("");
    action.setError("");
    setDetail((d) => ({ ...d, ...p }));
    setDirty(true);
  }
  function close() {
    if (action.busy) return;
    if (!dirty || window.confirm("Discard unsaved dish details?")) {
      setDetail(null);
      setDirty(false);
    }
  }
  function download(d: Row, a: Row) {
    setDownloadIds([a.id]);
  }
  function reuse(d: Row, a: Row, where: string) {
    if (dirty && !window.confirm("Discard unsaved dish details and continue?"))
      return;
    setDetail(null);
    setDirty(false);
    onDestination(where, d.id, a.id, { quick: true });
  }
  function UsePhoto({ dish, photo }: { dish: Row; photo: Row }) {
    return (
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button className="cx-link">
            Use photo <ChevronDown size={14} />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent className="cx-workspace-popover" align="end">
          <DropdownMenuItem onSelect={() => reuse(dish, photo, "post")}>
            Make a post
          </DropdownMenuItem>
          <DropdownMenuItem onSelect={() => reuse(dish, photo, "menu")}>
            Add to menu
          </DropdownMenuItem>
          <DropdownMenuItem onSelect={() => download(dish, photo)}>
            Download photo
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    );
  }
  async function archiveDish(d: Row, value: boolean) {
    await api(`library/${d.id}`, { archived: value });
    await refresh();
    setUndo({ id: d.id, name: d.name, archived: !value });
    setDetail(null);
    setSelected((ids) => ids.filter((id) => id !== d.id));
    action.setNotice(
      value
        ? `${d.name} archived. Existing posts and published menus stay available.`
        : `${d.name} restored.`,
    );
  }
  async function uploadAll() {
    for (const item of uploads) {
      if (item.assetId) continue;
      if (!item.name.trim()) throw Error("Name each dish before uploading.");
      setUploads((prev) =>
        prev.map((u) =>
          u.key === item.key ? { ...u, status: "Uploading…" } : u,
        ),
      );
      try {
        const dishId =
          item.dishId ||
          (await api("dishes", { name: item.name, confirmed: true })).id;
        setUploads((prev) =>
          prev.map((u) => (u.key === item.key ? { ...u, dishId } : u)),
        );
        const fd = new FormData();
        fd.set("dishId", dishId);
        fd.set("file", item.file);
        fd.set("normalized", await normalizePhoto(item.file), "working.jpg");
        const data = await api("assets", fd);
        setUploads((prev) =>
          prev.map((u) =>
            u.key === item.key
              ? { ...u, dishId, assetId: data.id, status: "Ready for review" }
              : u,
          ),
        );
      } catch (e) {
        setUploads((prev) =>
          prev.map((u) =>
            u.key === item.key ? { ...u, status: (e as Error).message } : u,
          ),
        );
        await refresh();
        throw e;
      }
    }
    await refresh();
    action.setNotice("Photos uploaded. Open each dish to review its photo.");
  }
  return (
    <section className="mm-workspace mm-library">
      <CreativeHeader
        title="My Dishes"
        status={`${allDishes.filter((d) => !d.archived_at).length} dishes`}
        action={
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="cx-btn">
                <Plus size={16} /> Add dishes <ChevronDown size={15} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="cx-workspace-popover" align="end">
              <DropdownMenuItem
                onSelect={() => {
                  setAdding(true);
                  setNewName("");
                }}
              >
                Add a dish
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => files.current?.click()}>
                Upload photos
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={onImports}>
                Import a menu
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        }
      />
      <Feedback {...action} />
      {undo && (
        <div className="mm-inline mm-muted">
          <button
            className="cx-link"
            disabled={!!action.busy}
            onClick={() =>
              action.act("Undoing archive", async () => {
                for (const id of undo.ids || [undo.id])
                  await api(`library/${id}`, { archived: undo.archived });
                await refresh();
                setUndo(null);
                action.setNotice("Archive change undone.");
              })
            }
          >
            Undo {undo.archived ? "restore" : "archive"}
          </button>
        </div>
      )}
      <div className="mm-toolbar mm-library-toolbar">
        <input
          type="search"
          aria-label="Find a dish"
          placeholder="Find a dish…"
          value={search}
          onChange={(event) => setSearch(event.target.value)}
        />
        <button
          className="cx-btn cx-secondary"
          onClick={() => setFiltersOpen(true)}
          aria-label={`Filters${filterCount ? `, ${filterCount} active` : ""}`}
        >
          <SlidersHorizontal size={16} /> Filters{" "}
          {filterCount > 0 && (
            <span className="mm-filter-count">{filterCount}</span>
          )}
        </button>
        <button
          className="cx-link mm-select-toggle"
          aria-pressed={selecting}
          onClick={() => {
            setSelecting(!selecting);
            setSelected([]);
          }}
        >
          {selecting ? "Done" : "Select"}
        </button>
      </div>
      {(search || filterCount > 0 || sort !== "recent") && (
        <div className="mm-filter-summary">
          <span>
            {dishes.length} {archived ? "archived " : ""}
            {dishes.length === 1 ? "dish" : "dishes"}
            {sort === "name" ? " · Name A–Z" : ""}
          </span>
          {dishes.length > 0 && (
            <button className="cx-link" onClick={clearFilters}>
              Clear filters
            </button>
          )}
        </div>
      )}
      <Sheet open={filtersOpen} onOpenChange={setFiltersOpen}>
        <SheetContent
          className="cx-app mm-drawer mm-filter-drawer"
          aria-describedby={undefined}
        >
          <SheetTitle>Filter your dishes</SheetTitle>
          <div className="mm-filter-fields">
            <Field label="Section">
              <select
                value={section}
                onChange={(event) => setSection(event.target.value)}
              >
                <option value="">All sections</option>
                {[...new Set(allDishes.map((dish) => dish.category))].map(
                  (name) => (
                    <option key={name}>{name}</option>
                  ),
                )}
              </select>
            </Field>
            <Field label="Photo status">
              <select
                value={status}
                onChange={(event) => setStatus(event.target.value)}
              >
                <option value="">All photos</option>
                {["Ready to use", "Needs review", "No photo"].map((value) => (
                  <option key={value}>{value}</option>
                ))}
              </select>
            </Field>
            <Field label="Sort dishes">
              <select
                value={sort}
                onChange={(event) => setSort(event.target.value)}
              >
                <option value="recent">Recently updated</option>
                <option value="name">Name A–Z</option>
              </select>
            </Field>
            <label className="cx-check mm-archive-filter">
              <input
                type="checkbox"
                checked={archived}
                onChange={(event) => {
                  setArchived(event.target.checked);
                  setSelected([]);
                  setSelecting(false);
                  if (selected.length)
                    action.setNotice(
                      "Selection cleared when switching between active and archived dishes.",
                    );
                }}
              />{" "}
              Show archived dishes
            </label>
          </div>
          <footer className="mm-filter-footer">
            <p role="status">
              {dishes.length} matching {dishes.length === 1 ? "dish" : "dishes"}
            </p>
            <button className="cx-btn" onClick={() => setFiltersOpen(false)}>
              Show results
            </button>
            <button className="cx-link" onClick={clearFilters}>
              Reset filters & sort
            </button>
          </footer>
        </SheetContent>
      </Sheet>
      {selected.length > 0 && (
        <div className="mm-bulk">
          <strong>{selected.length} selected</strong>
          <button
            className="cx-link"
            onClick={() => {
              const ids = selected
                .map((id) =>
                  preferredPhoto(
                    allDishes.find((d) => d.id === id)!,
                    state.assets,
                  ),
                )
                .filter((a) => a?.approved_at)
                .map((a) => a.id);
              if (ids.length !== selected.length)
                action.setError(
                  "Choose dishes with approved photos to download.",
                );
              else setDownloadIds(ids);
            }}
          >
            Download photos
          </button>
          <button
            className="cx-link"
            disabled={!!action.busy}
            onClick={() =>
              action.act("Updating dishes", async () => {
                for (const id of selected)
                  await api(`library/${id}`, { archived: !archived });
                await refresh();
                setUndo({ ids: [...selected], archived });
                setSelected([]);
                action.setNotice(
                  archived
                    ? "Dishes restored."
                    : "Dishes archived. Their saved work remains available.",
                );
              })
            }
          >
            {archived ? "Restore" : "Archive"}
          </button>
        </div>
      )}
      {!dishes.length ? (
        <div className="mm-empty">
          <Images size={32} />
          <h2>
            {search || section || status
              ? "No dishes match these filters."
              : archived
                ? "No archived dishes."
                : "Your dishes, ready for their next appearance."}
          </h2>
          <button
            className="cx-link"
            onClick={() => {
              if (search || section || status) {
                setSearch("");
                setSection("");
                setStatus("");
              } else if (archived) {
                setArchived(false);
              } else {
                setAdding(true);
                setNewName("");
              }
            }}
          >
            {search || section || status
              ? "Clear filters"
              : archived
                ? "View active dishes"
                : "Add your first dish"}
          </button>
        </div>
      ) : (
        <div className="mm-library-grid">
          {dishes.map((d) => {
            const a = preferredPhoto(d, state.assets);
            const label = dishStatus(d, state.assets);
            return (
              <article
                className="mm-dish-card"
                key={d.id}
                data-selected={selecting && selected.includes(d.id)}
                data-has-photo={!!a}
              >
                <button
                  className="mm-dish-open"
                  aria-label={`Open ${d.name}`}
                  onClick={() => open(d)}
                >
                  {a ? (
                    <img
                      src={`/api/assets/${a.id}`}
                      alt={d.name}
                      loading="lazy"
                    />
                  ) : (
                    <div className="mm-dish-placeholder">
                      <UtensilsCrossed size={20} />
                      <span>No photo yet</span>
                    </div>
                  )}
                  <span>
                    <span className="mm-dish-title">
                      <strong>{d.name}</strong>
                      {Number.isFinite(d.price) && (
                        <span className="mm-dish-price">
                          {money(d.price, state.restaurant.currency)}
                        </span>
                      )}
                    </span>
                    <small>{d.category}</small>
                  </span>
                </button>
                {selecting && (
                  <label className="mm-card-select">
                    <input
                      type="checkbox"
                      aria-label={`Select ${d.name}`}
                      checked={selected.includes(d.id)}
                      disabled={
                        !selected.includes(d.id) && selected.length >= 10
                      }
                      onChange={(e) =>
                        setSelected(
                          e.target.checked
                            ? [...selected, d.id]
                            : selected.filter((id) => id !== d.id),
                        )
                      }
                    />
                  </label>
                )}
                <footer>
                  <span
                    className={`mm-status ${a?.approved_at ? "ready" : a ? "needs-review" : ""}`}
                  >
                    {a?.approved_at ? (
                      <Check size={15} aria-hidden="true" />
                    ) : a ? (
                      <CircleAlert size={15} aria-hidden="true" />
                    ) : (
                      <Images size={15} aria-hidden="true" />
                    )}{" "}
                    {label}
                  </span>
                  {a?.approved_at ? (
                    <UsePhoto dish={d} photo={a} />
                  ) : (
                    <button className="cx-link" onClick={() => open(d)}>
                      {a ? "Review" : "Add photo"}
                    </button>
                  )}
                </footer>
              </article>
            );
          })}
        </div>
      )}
      <Sheet
        open={!!detail}
        onOpenChange={(v) => {
          if (!v) close();
        }}
      >
        <SheetContent
          className="cx-app mm-drawer mm-dish-detail-drawer"
          aria-describedby={undefined}
          closeDisabled={!!action.busy}
        >
          <SheetTitle>{detail?.name}</SheetTitle>
          <fieldset className="mm-dish-detail-body" disabled={!!action.busy}>
            {detail && (
              <>
                <div className="mm-detail-grid">
                  <div>
                    {current ? (
                      <img
                        className="mm-detail-photo"
                        src={`/api/assets/${current.id}`}
                        alt={detail.name}
                      />
                    ) : (
                      <div className="mm-detail-photo mm-empty">
                        <Images size={40} />
                        <p>No photo yet</p>
                      </div>
                    )}
                    {!!photos.length && (
                      <div
                        className="mm-version-list"
                        aria-label="Photo versions"
                      >
                        {photos.map((a, n) => (
                          <button
                            key={a.id}
                            aria-pressed={current?.id === a.id}
                            onClick={() => setChosen(a.id)}
                          >
                            <img
                              src={`/api/assets/${a.id}`}
                              alt={
                                a.kind === "source"
                                  ? "Original"
                                  : `Version ${n + 1}`
                              }
                            />
                            <small>
                              {a.id === currentDish?.preferred_photo_id
                                ? "Main photo"
                                : a.kind === "source"
                                  ? "Original"
                                  : a.approved_at
                                    ? "Approved"
                                    : "Needs review"}
                            </small>
                          </button>
                        ))}
                      </div>
                    )}
                    {current && (
                      <p className="mm-muted">
                        {new Date(current.created_at).toLocaleDateString()} ·{" "}
                        {current.kind === "source"
                          ? "Original photo"
                          : current.kind === "edited"
                            ? "Adjusted version"
                            : "Studio version"}
                      </p>
                    )}
                    <div className="mm-detail-actions">
                      {current?.approved_at ? (
                        <>
                          <UsePhoto dish={detail} photo={current} />
                          <button
                            className="cx-link"
                            disabled={
                              current.id === currentDish?.preferred_photo_id ||
                              !!action.busy
                            }
                            onClick={() =>
                              action.act("Setting main photo", async () => {
                                await api(`library/${detail.id}`, {
                                  preferredPhotoId: current.id,
                                });
                                await refresh();
                                action.setNotice(
                                  "Main photo updated for new creations.",
                                );
                              })
                            }
                          >
                            <Star size={15} />
                            {current.id === currentDish?.preferred_photo_id
                              ? "Main photo"
                              : "Make main photo"}
                          </button>
                        </>
                      ) : current ? (
                        <label className="cx-check">
                          <input
                            type="checkbox"
                            checked={false}
                            disabled={!!action.busy}
                            onChange={() =>
                              action.act("Approving photo", async () => {
                                await api(`assets/${current.id}/approve`, {
                                  accurate: true,
                                });
                                await refresh();
                                action.setNotice(
                                  "Photo approved and ready to use.",
                                );
                              })
                            }
                          />
                          This photo accurately shows the dish I serve
                        </label>
                      ) : null}
                      <button
                        className="cx-link"
                        onClick={() => {
                          if (
                            dirty &&
                            !window.confirm(
                              "Discard unsaved dish details and continue?",
                            )
                          )
                            return;
                          setDetail(null);
                          setDirty(false);
                          onPhoto(detail.id, current?.id);
                        }}
                      >
                        {current ? "Open in Photo Studio" : "Add a photo"}
                      </button>
                    </div>
                    {photos.some((a) => a.kind === "source") && (
                      <a
                        className="cx-link"
                        download
                        href={`/api/assets/${photos.find((a) => a.kind === "source")!.id}?original=1&download=1`}
                      >
                        Download untouched original
                      </a>
                    )}
                    <details className="mm-divider mm-dish-usage">
                      <summary>
                        Used in {usage.length} saved{" "}
                        {usage.length === 1 ? "design" : "designs"}
                      </summary>
                      {usageError ? (
                        <p role="alert" className="mm-muted">
                          {usageError}
                        </p>
                      ) : usage.length ? (
                        usage.map((u) => (
                          <div key={u.id} className="mm-inline">
                            <button
                              className="cx-link"
                              onClick={() => {
                                if (
                                  dirty &&
                                  !window.confirm(
                                    "Discard unsaved dish details and continue?",
                                  )
                                )
                                  return;
                                setDetail(null);
                                setDirty(false);
                                onOpenWork(u.kind, u.id);
                              }}
                            >
                              {u.title}
                            </button>
                            <span className="mm-muted">
                              {u.kind === "post" ? "Post" : "Menu"}
                              {u.changed ? " · Details changed" : ""}
                            </span>
                          </div>
                        ))
                      ) : (
                        <p className="mm-muted">
                          No saved posts or menus use this dish yet.
                        </p>
                      )}
                      <p className="mm-muted">
                        Saved designs keep their details. Publish menu changes
                        when you’re ready.
                      </p>
                    </details>
                  </div>
                  <fieldset className="mm-dish-fields" disabled={!!action.busy}>
                    <Field label="Dish name">
                      <input
                        maxLength={100}
                        value={detail.name}
                        onChange={(e) => edit({ name: e.target.value })}
                      />
                    </Field>
                    <Field label={`Price (${state.restaurant.currency})`}>
                      <input
                        type="number"
                        min="0"
                        max="1000000"
                        step=".01"
                        value={detail.price}
                        onChange={(e) => edit({ price: e.target.value })}
                      />
                    </Field>
                    <Field label="Description">
                      <textarea
                        rows={4}
                        maxLength={2000}
                        value={detail.description}
                        onChange={(e) => edit({ description: e.target.value })}
                      />
                    </Field>
                    <Field label="Section">
                      <input
                        maxLength={100}
                        value={detail.category}
                        onChange={(e) => edit({ category: e.target.value })}
                      />
                    </Field>
                    <label className="cx-check">
                      <input
                        type="checkbox"
                        checked={detail.available}
                        onChange={(e) => edit({ available: e.target.checked })}
                      />
                      Available
                    </label>
                    {dirty && (
                      <p className="mm-muted">
                        Changes will be flagged in linked designs. Your
                        published menu stays as it is until you republish.
                      </p>
                    )}
                    <div className="mm-divider">
                      <button
                        className="cx-link"
                        disabled={!!action.busy}
                        onClick={() =>
                          action.act("Updating dish", () =>
                            archiveDish(detail, !detail.archived_at),
                          )
                        }
                      >
                        <Archive size={16} />
                        {detail.archived_at ? "Restore dish" : "Archive dish"}
                      </button>
                      {current && (
                        <details>
                          <summary className="mm-muted">
                            Manage this photo
                          </summary>
                          <button
                            className="cx-link"
                            onClick={() => setDeleting(current.id)}
                          >
                            Delete photo permanently
                          </button>
                        </details>
                      )}
                    </div>
                  </fieldset>
                </div>
              </>
            )}
          </fieldset>
          {detail && (
            <footer className="mm-dish-detail-footer">
              <Feedback {...action} />
              {!action.notice && !action.error && !action.busy && (
                <span className="mm-muted" role="status">
                  {dirty ? "Unsaved changes" : "Details saved"}
                </span>
              )}
              <button
                className="cx-btn"
                disabled={!dirty || !!action.busy}
                onClick={() =>
                  action.act("Saving dish", async () => {
                    if (
                      detail.price === "" ||
                      !Number.isFinite(Number(detail.price)) ||
                      Number(detail.price) < 0 ||
                      Number(detail.price) > 1000000
                    )
                      throw Error(
                        "Enter a price from 0 to 1,000,000. Use 0 only if this dish is free.",
                      );
                    const saved = await api(`dishes/${detail.id}`, {
                      ...detail,
                      price: Number(detail.price),
                      confirmed: true,
                    });
                    await refresh();
                    setDetail((d) => ({ ...d, revision: saved.revision }));
                    setDirty(false);
                    action.setNotice("Dish details saved.");
                  })
                }
              >
                Save details
              </button>
            </footer>
          )}
        </SheetContent>
      </Sheet>
      <input
        ref={files}
        hidden
        type="file"
        multiple
        accept="image/jpeg,image/png,image/heic,image/heif"
        onChange={(e) => {
          const list = Array.from(e.target.files || []);
          e.target.value = "";
          if (list.length > 10) {
            action.setError("Upload up to 10 photos at a time.");
            return;
          }
          setUploads(
            list.map((file) => ({
              key: crypto.randomUUID(),
              file,
              url: URL.createObjectURL(file),
              name: file.name.replace(/\.[^.]+$/, "").replace(/[-_]/g, " "),
              status: "Ready to upload",
            })),
          );
        }}
      />
      <Dialog open={adding} onOpenChange={setAdding}>
        <DialogContent
          className="cx-app mm-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>Add a dish</DialogTitle>
          <Field label="Dish name">
            <input
              autoFocus
              value={newName}
              maxLength={100}
              onChange={(e) => setNewName(e.target.value)}
            />
          </Field>
          <p className="mm-muted">
            You can add a photo and other details later.
          </p>
          <Feedback {...action} />
          <button
            className="cx-btn"
            disabled={!newName.trim() || !!action.busy}
            onClick={() =>
              action.act("Adding dish", async () => {
                const { id, revision } = await api("dishes", {
                  name: newName,
                  confirmed: true,
                });
                await refresh();
                setAdding(false);
                open({
                  id,
                  revision,
                  name: newName,
                  description: "",
                  category: "Dishes",
                  price: 0,
                  available: true,
                });
              })
            }
          >
            Add dish
          </button>
        </DialogContent>
      </Dialog>
      <Dialog
        open={uploads.length > 0}
        onOpenChange={(v) => {
          if (!v && !action.busy) {
            uploads.forEach((u) => URL.revokeObjectURL(u.url));
            setUploads([]);
          }
        }}
      >
        <DialogContent
          className="cx-app mm-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>Upload dish photos</DialogTitle>
          <p className="mm-muted">
            One dish per photo. Check the names, then upload. Originals are
            retained.
          </p>
          <div className="mm-upload-rows">
            {uploads.map((u) => (
              <div className="mm-upload-row" key={u.key}>
                <img src={u.url} alt="Photo to upload" />
                <div>
                  <input
                    aria-label={`Dish name for ${u.file.name}`}
                    value={u.name}
                    maxLength={100}
                    disabled={!!u.dishId}
                    onChange={(e) =>
                      setUploads((prev) =>
                        prev.map((x) =>
                          x.key === u.key ? { ...x, name: e.target.value } : x,
                        ),
                      )
                    }
                  />
                  <p role="status">{u.status}</p>
                </div>
                {u.assetId && <Check size={18} />}
              </div>
            ))}
          </div>
          <Feedback {...action} />
          <button
            className="cx-btn"
            disabled={!!action.busy || uploads.some((u) => !u.name.trim())}
            onClick={() =>
              uploads.every((u) => u.assetId)
                ? (uploads.forEach((u) => URL.revokeObjectURL(u.url)),
                  setUploads([]))
                : action.act("Uploading photos", uploadAll)
            }
          >
            {uploads.every((u) => u.assetId)
              ? "Done"
              : action.busy || "Upload photos"}
          </button>
        </DialogContent>
      </Dialog>
      <Dialog
        open={downloadIds.length > 0}
        onOpenChange={(v) => {
          if (!v) setDownloadIds([]);
        }}
      >
        <DialogContent
          className="cx-app cx-export-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>
            {downloadIds.length > 1
              ? "Download selected photos"
              : "Download photo"}
          </DialogTitle>
          <PhotoDownloads
            key={downloadIds.join(":")}
            items={downloadIds
              .map((id) => {
                const a = state.assets.find(
                  (a: Row) => a.id === id && a.approved_at,
                );
                const d = a && allDishes.find((d) => d.id === a.dish_id);
                return a && d ? downloadPhotoItem(state, a, d.name) : null;
              })
              .filter((item) => item !== null)}
            preferenceKey={workspacePreferenceKey(
              state.user.id,
              state.restaurant.id,
            )}
            onPromote={(item) => {
              setDownloadIds([]);
              reuse({ id: item.dishId }, { id: item.assetId }, "post");
            }}
          />
        </DialogContent>
      </Dialog>
      <ConfirmDelete
        open={!!deleting}
        onClose={() => setDeleting("")}
        onConfirm={() => {
          const id = deleting;
          setDeleting("");
          void action.act("Deleting photo", async () => {
            await api(`assets/${id}`, undefined, "DELETE");
            await refresh();
            setChosen("");
            action.setNotice(
              "Photo deleted. Published references were removed.",
            );
          });
        }}
      />
    </section>
  );
}

"use client";

import { useRef, useState } from "react";
import { ArrowRight, Search, X } from "lucide-react";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog";
import { exploreStyles } from "@/lib/explore-styles";
import type { PhotoStyle } from "@/lib/photo-styles";
import { maximumStyleQueryLength, searchStyles } from "@/lib/studio-search";

export default function ExploreGallery({
  active = true,
  disabledStyleIds = [],
  onTryStyle,
}: {
  active?: boolean;
  disabledStyleIds?: string[];
  onTryStyle: (styleId: string) => void;
}) {
  const [selected, setSelected] = useState<PhotoStyle | null>(null);
  const [query, setQuery] = useState("");
  const trigger = useRef<HTMLButtonElement | null>(null);
  const searchInput = useRef<HTMLInputElement | null>(null);
  const trying = useRef(false);
  const available = exploreStyles.filter(
    (style) => !disabledStyleIds.includes(style.id),
  );
  const unavailable = !!selected && disabledStyleIds.includes(selected.id);
  const results = searchStyles(query, "All", available);

  return (
    <section className="ex-gallery" aria-labelledby="explore-title">
      <header className="ex-header">
        <h1 id="explore-title" tabIndex={-1}>
          All Styles
        </h1>
        <div className="ex-search" role="search" aria-label="Explore styles">
          <Search size={18} aria-hidden="true" />
          <input
            ref={searchInput}
            aria-label="Search styles"
            type="text"
            role="searchbox"
            placeholder="Search a style, mood or setting"
            value={query}
            maxLength={maximumStyleQueryLength}
            onChange={(event) => setQuery(event.target.value)}
          />
          {query && (
            <button
              type="button"
              aria-label="Clear style search"
              onClick={() => {
                setQuery("");
                searchInput.current?.focus();
              }}
            >
              <X size={18} />
            </button>
          )}
        </div>
      </header>
      {query && (
        <p className="ex-search-summary" role="status">
          {results.styles.length}{" "}
          {results.styles.length === 1 ? "style" : "styles"}
          {results.related ? " · Related looks included" : ""}
        </p>
      )}
      <div className="ex-grid">
        {results.styles.map((style, index) => (
          <button
            key={style.id}
            type="button"
            className="ex-tile"
            data-explore-style={style.id}
            aria-label={`Explore ${style.name} — ${style.group}`}
            aria-haspopup="dialog"
            onClick={(event) => {
              trigger.current = event.currentTarget;
              trying.current = false;
              setSelected(style);
            }}
          >
            <span className="ex-tile-image">
              <img
                src={style.image}
                alt={`${style.name} food photography style: ${style.cue}`}
                width={1000}
                height={1000}
                loading={index < 3 ? "eager" : "lazy"}
                decoding="async"
              />
            </span>
            <span className="ex-tile-caption">
              <strong>{style.name}</strong>
              <span>{style.group}</span>
            </span>
          </button>
        ))}
      </div>
      {available.length === 0 && (
        <p className="cx-feedback" role="status">
          Styles are being refreshed. Please check back soon.
        </p>
      )}
      {!!available.length && !results.styles.length && (
        <div className="ex-empty" role="status">
          <h2>No styles found</h2>
          <p>Try a mood, color or setting, or return to all styles.</p>
          <button
            className="cx-btn cx-secondary"
            onClick={() => {
              setQuery("");
              searchInput.current?.focus({ preventScroll: true });
              window.scrollTo({ top: 0, behavior: "instant" });
            }}
          >
            Show all styles
          </button>
        </div>
      )}

      <Dialog
        open={active && !!selected}
        onOpenChange={(open) => !open && setSelected(null)}
      >
        <DialogContent
          className="ex-detail"
          showCloseButton={false}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            if (!trying.current)
              trigger.current?.focus({ preventScroll: true });
          }}
        >
          {selected && (
            <>
              <div className="ex-detail-scroll">
                <div className="ex-detail-photo">
                  <img
                    src={selected.image}
                    alt={`${selected.name} style example: ${selected.cue}`}
                    width={1000}
                    height={1000}
                  />
                </div>
                <div className="ex-detail-info">
                  <div>
                    <p className="ex-category">{selected.group}</p>
                    <DialogTitle className="ex-detail-title">
                      {selected.name}
                    </DialogTitle>
                    <DialogDescription className="ex-description">
                      {selected.description || selected.cue}
                    </DialogDescription>
                    {!!selected.traits?.length && (
                      <ul className="ex-traits" aria-label="Style details">
                        {selected.traits.map((trait) => (
                          <li key={trait}>{trait}</li>
                        ))}
                      </ul>
                    )}
                    {selected.bestFor && (
                      <div className="ex-best-for">
                        <h3>Perfect for</h3>
                        <p>{selected.bestFor}</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
              <footer className="ex-detail-action">
                <button
                  type="button"
                  className="ex-try"
                  disabled={unavailable}
                  onClick={() => {
                    trying.current = true;
                    setSelected(null);
                    onTryStyle(selected.id);
                  }}
                >
                  {unavailable ? "Temporarily unavailable" : "Use this look"}
                  {!unavailable && <ArrowRight size={18} aria-hidden="true" />}
                </button>
                <small>AI-generated style example</small>
              </footer>
              <DialogClose
                className="ex-close"
                aria-label="Close style details"
              >
                <X size={20} aria-hidden="true" />
              </DialogClose>
            </>
          )}
        </DialogContent>
      </Dialog>
    </section>
  );
}

"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowLeft, Sparkles } from "lucide-react";
import { api, normalizePhoto, type Row } from "@/lib/client";
import {
  emptyAdjustments,
  looks,
  photoBrief,
  resolvePhotoLook,
  unavailablePhotoLook,
} from "@/lib/studio";
import {
  clearGuestDraft,
  loadGuestDrafts,
  restoreGuestPhoto,
  saveGuestDraft,
  type GuestDraftRecord,
} from "@/lib/guest-studio-storage";
import { studioLookPatch } from "@/lib/studio-discovery";
import { activeInspirationId, inspirationPatch } from "@/lib/studio-reference";
import {
  transferGuestPhoto,
  type GuestPhoto,
  type GuestTransfer,
} from "@/lib/guest-studio";
import Brand from "./brand";
import { StudioWorkbench } from "./studio-workbench";
export default function GuestStudio({
  state,
  onSignIn,
  onSignup,
  onFinish,
  onBack,
}: {
  state: Row;
  onSignIn: () => void;
  onSignup: () => void;
  onFinish: () => Promise<void>;
  onBack: () => void;
}) {
  const [draft, setDraft] = useState<Row>(() => photoBrief());
  const [photo, setPhoto] = useState<GuestPhoto | null>(null),
    [reference, setReference] = useState<GuestPhoto | null>(null);
  const [busy, setBusy] = useState(""),
    [referenceBusy, setReferenceBusy] = useState(false),
    [error, setError] = useState(""),
    [requested, setRequested] = useState(false);
  const lock = useRef(false),
    urls = useRef<string[]>([]);
  const transfer = useRef<GuestTransfer | null>(null);
  const latest = useRef({ draft, photo, reference });
  const localId = useRef(""),
    persisted = useRef(false),
    transferring = useRef(false);
  const saving = useRef<Promise<unknown>>(Promise.resolve());
  const [storageReady, setStorageReady] = useState(false),
    [storageNotice, setStorageNotice] = useState(""),
    [recoverable, setRecoverable] = useState<GuestDraftRecord[]>([]);
  useEffect(() => {
    let active = true;
    localId.current = crypto.randomUUID();
    void loadGuestDrafts()
      .then((records) => {
        if (active)
          setRecoverable(
            records.filter(
              (record) => record.photo || record.draft.mode === "description",
            ),
          );
      })
      .catch(() => {
        if (active)
          setStorageNotice(
            "This browser can’t keep your draft after you leave. Keep this tab open until your photo is saved to your account.",
          );
      })
      .finally(() => {
        if (active) setStorageReady(true);
      });
    return () => {
      active = false;
    };
  }, []);
  async function persistLocal(nextRequested = requested) {
    const recordId = localId.current;
    const value = {
      ...latest.current,
      transfer: transfer.current ? { ...transfer.current } : null,
      requested: nextRequested,
    };
    const pending = saving.current
      .catch(() => {})
      .then(() => saveGuestDraft(recordId, value));
    saving.current = pending;
    await pending;
    persisted.current = true;
  }
  useEffect(() => {
    if (
      !storageReady ||
      transferring.current ||
      (!photo && !draft.styleIntent && draft.mode !== "description")
    )
      return;
    persisted.current = false;
    const timer = setTimeout(() => {
      if (transferring.current) return;
      void persistLocal().catch(() =>
        setStorageNotice(
          "This browser couldn’t save your draft. Keep this tab open, or try again.",
        ),
      );
    }, 200);
    return () => clearTimeout(timer);
  }, [draft, photo, reference, requested, storageReady]);
  function resume(record: GuestDraftRecord) {
    localId.current = record.id;
    transfer.current = record.transfer;
    const restoredPhoto = restoreGuestPhoto(record.photo),
      restoredReference = restoreGuestPhoto(record.reference);
    for (const photo of [restoredPhoto, restoredReference])
      if (photo) urls.current.push(photo.url);
    setDraft(record.draft);
    setPhoto(restoredPhoto);
    setReference(restoredReference);
    setRecoverable([]);
    latest.current = {
      draft: record.draft,
      photo: restoredPhoto,
      reference: restoredReference,
    };
    // Resuming restores work; creation always requires the owner's action.
    setRequested(false);
    persisted.current = true;
    setSavedSome(!!record.transfer?.dishId);
    setStorageNotice(
      "Draft restored. Check your choices, then create when you’re ready.",
    );
  }
  useEffect(() => {
    latest.current = { draft, photo, reference };
  }, [draft, photo, reference]);
  useEffect(() => {
    const retained = new Set([photo?.url, reference?.url]);
    urls.current = urls.current.filter((url) => {
      if (retained.has(url)) return true;
      URL.revokeObjectURL(url);
      return false;
    });
  }, [photo, reference]);
  const autoStarted = useRef("");
  const [savedSome, setSavedSome] = useState(false);
  useEffect(
    () => () => {
      urls.current.forEach((url) => URL.revokeObjectURL(url));
    },
    [],
  );
  useEffect(() => {
    const warn = (e: BeforeUnloadEvent) => {
      if (
        latest.current.photo &&
        !persisted.current &&
        !transfer.current?.jobId
      )
        e.preventDefault();
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, []);
  const continueCreation = useCallback(async () => {
    if (lock.current) return;
    lock.current = true;
    transferring.current = true;
    setBusy("Creating your photo");
    setError("");
    try {
      transfer.current ||= {
        id: crypto.randomUUID(),
        revision: 0,
        requestKey: crypto.randomUUID(),
      };
      await transferGuestPhoto(
        latest.current.draft,
        latest.current.photo,
        latest.current.reference,
        state,
        transfer.current,
        async () => {
          await persistLocal(true).catch(() => {
            setStorageNotice(
              "Keep this tab open while your photo is saved to your account.",
            );
          });
        },
      );
      await saving.current.catch(() => {});
      await clearGuestDraft(localId.current).catch(() => {});
      void api("jobs/tick", {}).catch(() => {});
      await onFinish();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      lock.current = false;
      transferring.current = false;
      setBusy("");
      setSavedSome(!!transfer.current?.dishId);
    }
  }, [state, onFinish]);
  useEffect(() => {
    if (state.user && requested && autoStarted.current !== state.user.id) {
      autoStarted.current = state.user.id;
      queueMicrotask(() => void continueCreation());
    }
  }, [state.user, requested, continueCreation]);
  function update(patch: Row) {
    setDraft((d) => ({ ...d, ...patch, styleChosen: true }));
    if (!transfer.current?.dishId) transfer.current = null;
    else {
      transfer.current = {
        ...transfer.current,
        requestKey: crypto.randomUUID(),
        ...(transfer.current.jobId
          ? {
              id: crypto.randomUUID(),
              revision: 0,
              jobId: undefined,
              startedAt: undefined,
            }
          : {}),
      };
      if ("sourceId" in patch) {
        transfer.current.sourceId = undefined;
        transfer.current.sourceRequestKey = undefined;
      }
      if ("referenceId" in patch) {
        transfer.current.referenceId = undefined;
        transfer.current.referenceRequestKey = undefined;
      }
    }
  }
  async function upload(file: File) {
    if (lock.current) return;
    lock.current = true;
    setBusy("Preparing your photo");
    setError("");
    try {
      const normalized = await normalizePhoto(file),
        url = URL.createObjectURL(normalized);
      urls.current.push(url);
      const next = { file, normalized, url };
      setPhoto(next);
      update({
        sourceId: "guest-photo",
        mode: "photo",
        analysisStatus: "manual",
        analysisSourceId: "guest-photo",
        adjustments: { ...emptyAdjustments },
      });
    } catch (e) {
      setError((e as Error).message);
    } finally {
      lock.current = false;
      setBusy("");
    }
  }
  async function create() {
    try {
      await persistLocal(true);
    } catch {
      setStorageNotice(
        "Your browser couldn’t save a local copy. Keep this tab open through sign-up.",
      );
    }
    setRequested(true);
    if (!state.user) onSignup();
    else void continueCreation();
  }
  const selected = resolvePhotoLook(draft) || unavailablePhotoLook;
  return (
    <div className="cx-guest">
      <header className="pw-header">
        <button
          className="cx-brand"
          onClick={onBack}
          disabled={!!busy}
          aria-label="Menu Material home"
        >
          <Brand />
        </button>
        <nav aria-label="Studio navigation">
          <a href="/pricing" target="_blank" rel="noreferrer">
            Plans
          </a>
          {!state.user && <button onClick={onSignIn}>Log in</button>}
          <span className="cx-guest-free">
            <Sparkles size={15} />5 free images
          </span>
        </nav>
      </header>
      <main id="creation-main" className="cx-main cx-feature-main">
        <section className="cx-tool cx-feature-page cx-guided-studio">
          <div className="cx-guest-heading">
            <div>
              <p className="cx-eyebrow">YOUR FIRST GREAT FOOD PHOTO</p>
              <h1>Photo Studio</h1>
              <p>Add your photo. Find your look. Make it menu material.</p>
            </div>
            <button className="cx-link" onClick={onBack} disabled={!!busy}>
              <ArrowLeft size={16} />
              Back
            </button>
          </div>
          {error && (
            <div className="cx-feedback error" role="alert">
              {error}
              {state.user && (
                <button
                  className="cx-link"
                  disabled={!!busy}
                  onClick={() => void continueCreation()}
                >
                  Retry creating my image
                </button>
              )}
              {state.user && savedSome && (
                <button
                  className="cx-link"
                  disabled={!!busy}
                  onClick={() => void onFinish()}
                >
                  Open my saved workspace
                </button>
              )}
            </div>
          )}
          {recoverable.length > 0 && !photo && (
            <div className="ps2-guest-recovery">
              <div>
                <b>Your photo is waiting.</b>
                <p>Saved on this device for 24 hours after your last change.</p>
              </div>
              <button
                className="cx-btn cx-secondary"
                onClick={() => resume(recoverable[0])}
              >
                Resume photo
              </button>
              <button className="cx-link" onClick={() => setRecoverable([])}>
                Start new
              </button>
            </div>
          )}
          {storageNotice && (
            <p className="ps2-inline-note" role="status">
              {storageNotice}
            </p>
          )}
          {busy && (
            <p role="status" className="cx-feedback">
              {busy}…
            </p>
          )}
          <StudioWorkbench
            draft={draft}
            state={{
              ...state,
              guest: !state.user,
              remaining: state.user ? state.remaining : 5,
              aiConnected: state.user ? state.aiConnected : true,
            }}
            selected={selected}
            source={photo?.url || ""}
            styleImage={
              draft.look === "reference"
                ? reference?.url || ""
                : draft.look === "keep"
                  ? photo?.url || selected.image
                  : selected.image
            }
            busy={busy || (referenceBusy ? "Preparing inspiration" : "")}
            advice=""
            update={update}
            chooseLook={(look) => {
              update(studioLookPatch(draft, look));
            }}
            matchRestaurant={() => {}}
            uploadPhoto={(file) => void upload(file)}
            referencePhoto={
              activeInspirationId(draft) && reference
                ? { id: "guest-reference", url: reference.url }
                : null
            }
            onReferenceBusyChange={setReferenceBusy}
            applyInspiration={async (selection, base, signal) => {
              if (signal.aborted) return;
              if (selection?.kind === "file") {
                const url = URL.createObjectURL(selection.normalized);
                urls.current.push(url);
                setReference({
                  file: selection.file,
                  normalized: selection.normalized,
                  url,
                });
              } else if (!selection) setReference(null);
              update(
                inspirationPatch(
                  base,
                  selection ? "guest-reference" : null,
                  selection?.kind === "existing",
                ),
              );
            }}
            create={create}
            quickEdit={() => {}}
            openMenu={() => {}}
          />
        </section>
      </main>
    </div>
  );
}

