const sharedFields = [
  "name",
  "description",
  "category",
  "price",
  "available",
  "portion",
  "plating",
  "setting",
  "preserve",
];
function dishFacts(d: Row) {
  return Object.fromEntries(
    sharedFields.map((key) => {
      const value =
        d[key] ??
        (key === "setting"
          ? "Natural daylight"
          : key === "category"
            ? "Dishes"
            : key === "price"
              ? 0
              : "");
      return [
        key,
        key === "available"
          ? !!d[key]
          : ["name", "description", "category"].includes(key)
            ? String(value).trim()
            : value,
      ];
    }),
  );
}
function withBaseline(d: Row) {
  return { ...d, _synced: dishFacts(d) };
}
function newerRows(rows: Row[], dishes: Row[]) {
  return rows.filter(
    (row) =>
      row.id &&
      row._synced &&
      dishes.some(
        (d) =>
          d.id === row.id &&
          JSON.stringify(dishFacts(d)) !== JSON.stringify(row._synced),
      ),
  );
}
function fromMenu(state: Row) {
  return state.restaurant.menuDraft.sections
    .flatMap((s: Row) =>
      s.items.map((i: Row) => {
        const d = state.dishes.find((d: Row) => d.id === i.dishId);
        return d
          ? {
              ...withBaseline(d),
              category: s.name,
              price: d.price / 100,
              available: !!d.available,
              photoId: i.photoId || "",
              featured:
                i.featured ??
                (state.restaurant.menuDraft.layout === "featured" &&
                  s.items[0] === i),
              crop: i.crop,
              rowId: d.id,
            }
          : null;
      }),
    )
    .filter(Boolean);
}
function blank() {
  return {
    rowId: crypto.randomUUID(),
    id: "",
    name: "",
    description: "",
    category: "Dishes",
    price: "",
    available: true,
    photoId: "",
  };
}
function menuContent(
  rows: Row[],
  restaurant: Row,
  layout: string,
  appearance: string,
  paper: string,
  options: Row = {},
) {
  const sections: Row[] = [];
  for (const row of rows) {
    let s = sections.find((s) => s.name === row.category);
    if (!s) {
      s = {
        id: String(sections.length),
        name: row.category || "Dishes",
        items: [],
      };
      sections.push(s);
    }
    s.items.push({
      ...row,
      id: row.id || row.rowId,
      price:
        row.price === "" || row.price == null
          ? NaN
          : Math.round(Number(row.price) * 100),
      photoId: row.photoId || null,
    });
  }
  return {
    restaurant: { ...restaurant, logoId: restaurant.logo_id },
    sections,
    design: options.design || "bistro",
    density: options.density || "comfortable",
    printProfile: options.printProfile || "home",
    title: options.title || "",
    layout,
    appearance,
    paper,
  };
}
export default function MenuBuilder({
