    [removed, setRemoved] = useState<{ row: Row; index: number } | null>(null);
  const [chooseDishes, setChooseDishes] = useState(false),
    [preview, setPreview] = useState("phone"),
    [pdf, setPdf] = useState<{
      url: string;
      blob: Blob;
      warnings: string[];
      pages: number;
    } | null>(null),
    [pdfError, setPdfError] = useState("");
  const seedHandled = useRef(""),
    pdfUrl = useRef(""),
    batchKey = useRef("");
