                          value={r.name}
                          maxLength={100}
                          onChange={(e) =>
                            edit(index, {
                              name: e.target.value,
                              importReviewed: false,
                            })
                          }
                        />
                      </Field>
                      <div className="mm-field-pair">
                        <Field label="Section">
                          <input
                            maxLength={100}
                            value={r.category}
                            onChange={(e) =>
                              edit(index, {
                                category: e.target.value,
                                importReviewed: false,
                              })
                            }
                          />
                        </Field>
                        <Field label="Price">
                          <input
                            type="number"
                            min="0"
                            step=".01"
                            value={r.price ?? ""}
                            placeholder="Unreadable"
                            onChange={(e) =>
                              edit(index, {
                                price: e.target.value,
                                importReviewed: false,
                              })
                            }
                          />
                        </Field>
                      </div>
                      <Field label="Description">
                        <textarea
                          rows={2}
                          maxLength={2000}
                          value={r.description}
                          onChange={(e) =>
                            edit(index, {
                              description: e.target.value,
                              importReviewed: false,
                            })
                          }
                        />
                      </Field>
                      <div className="mm-inline">
                        <label className="cx-check">
                          <input
                            type="checkbox"
                            checked={!!r.importReviewed}
                            disabled={
                              !r.name?.trim() ||
                              r.price == null ||
                              r.price === "" ||
                              Number(r.price) < 0 ||
                              !r.category?.trim()
                            }
                            onChange={(e) =>
                              edit(index, { importReviewed: e.target.checked })
                            }
                          />
                          Checked against original
                        </label>
                        <button
                          className="cx-link"
                          onClick={() =>
                            patch({ rows: rows.filter((_, i) => i !== index) })
                          }
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
              {rows.length > 0 && (
                <div className="mm-import-footer">
                  <span>
                    {rows.length - outstanding} of {rows.length} checked
                  </span>
                  <button className="cx-link" onClick={() => setBulkOpen(true)}>
                    Edit a section or prices
                  </button>
                  <button
                    className="cx-btn"
                    disabled={!!busy || !!outstanding}
                    onClick={() =>
                      act("Saving checked dishes", async () => {
                        await saveRows();
                        setImportOpen(false);
                      })
                    }
                  >
                    Use checked dishes
                  </button>
                </div>
              )}
            </>
          )}
          <Feedback {...action} />
        </DialogContent>
      </Dialog>
      <Dialog open={bulkOpen} onOpenChange={setBulkOpen}>
        <DialogContent
          className="cx-app mm-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>Edit a section</DialogTitle>
          <Field label="Section to edit">
            <select
              value={bulkSection}
              onChange={(e) => setBulkSection(e.target.value)}
            >
              <option value="">Choose a section</option>
              {sections.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </Field>
          <Field label="New section name (optional)">
            <input
              maxLength={100}
              value={bulkName}
              onChange={(e) => setBulkName(e.target.value)}
            />
          </Field>
          <Field label="Price change (%) · optional">
            <input
              type="number"
              min="-100"
              max="1000"
              placeholder="For example, 5 or -10"
              value={bulkPercent}
              onChange={(e) => setBulkPercent(e.target.value)}
            />
          </Field>
          <p className="mm-muted">
            Applies to {rows.filter((r) => r.category === bulkSection).length}{" "}
            dishes. Prices round to the nearest cent. Imported dishes must be
            checked again.
          </p>
          <button
            className="cx-btn"
            disabled={
              !bulkSection ||
              (!bulkName.trim() && bulkPercent === "") ||
              !Number.isFinite(Number(bulkPercent)) ||
              Number(bulkPercent) < -100 ||
              Number(bulkPercent) > 1000
            }
            onClick={() => {
              patch({
                rows: rows.map((r) =>
                  r.category === bulkSection
                    ? {
                        ...r,
                        category: bulkName.trim() || r.category,
                        price:
                          r.price === "" || r.price == null
                            ? r.price
                            : Math.round(
                                Number(r.price) *
                                  (1 + Number(bulkPercent) / 100) *
                                  100,
                              ) / 100,
                        importReviewed: false,
                      }
                    : r,
                ),
              });
              setBulkOpen(false);
              setBulkName("");
              setBulkPercent("");
            }}
          >
            Apply to section
          </button>
        </DialogContent>
      </Dialog>
      <Dialog open={completion} onOpenChange={setCompletion}>
        <DialogContent
          className="cx-app mm-dialog mm-menu-completion"
          aria-describedby={undefined}
        >
          <DialogTitle>Ready for your guests</DialogTitle>
          <div className="mm-segments">
            <button
              aria-pressed={destination === "publish"}
              onClick={() => setDestination("publish")}
            >
              Digital menu
            </button>
            <button
              aria-pressed={destination === "print"}
              onClick={() => setDestination("print")}
            >
              Print PDF
            </button>
          </div>
          {destination === "publish" ? (
            <>
              <p>Your existing link and QR code will keep working.</p>
              <div className="mm-publish-diff">
                <strong>
                  {changes.length
                    ? "Changes guests will see"
                    : "Your live menu is up to date"}
                </strong>
                {changes.map((c, n) => (
                  <p key={n}>{c}</p>
                ))}
              </div>
              <label className="cx-check">
                <input
                  type="checkbox"
                  checked={b.reviewed}
                  onChange={(e) => change({ reviewed: e.target.checked })}
                />
                I’ve checked the dishes, prices, photos, and availability.
              </label>
              <button
                className="cx-btn"
                disabled={!!busy || !b.reviewed || !changes.length}
                onClick={() =>
                  act("Publishing your menu", async () => {
                    await saveRows();
                    await api("menu/publish", {});
                    await refresh();
                    setCompletion(false);
                    setSharing(true);
                    setNotice(
                      "Your menu is live. The same link and QR code now show these changes.",
                    );
                  })
                }
              >
                {state.restaurant.published
                  ? "Publish changes"
                  : "Publish menu"}
              </button>
            </>
          ) : (
            <>
              {pdf ? (
                <>
                  <PrintPreview blob={pdf.blob} pages={pdf.pages} />
                  <p className="mm-muted">
                    {pdf.pages} {pdf.pages === 1 ? "page" : "pages"} ·{" "}
                    {b.paper === "a4" ? "A4" : "US Letter"} ·{" "}
                    {b.printProfile === "press"
                      ? "⅛-inch bleed and crop marks"
                      : "Finished page size"}
                  </p>
                  {pdf.warnings.map((w) => (
                    <p className="mm-output-notes" key={w}>
                      {w}
                    </p>
                  ))}
                  <label className="cx-check">
                    <input
                      type="checkbox"
                      checked={b.reviewed}
                      onChange={(e) => change({ reviewed: e.target.checked })}
                    />
                    I’ve checked each page and the print notes.
                  </label>
                  <button
                    className="cx-btn"
                    disabled={!!busy || !b.reviewed}
                    onClick={() => {
                      downloadBlob(
                        pdf.blob,
                        `${state.restaurant.slug}-menu-${b.paper}${b.printProfile === "press" ? "-print-shop" : ""}.pdf`,
                      );
                      setNotice("Your menu PDF download has started.");
                      track("export_complete", undefined, {
                        tool: "menu",
                        format: "pdf",
                      });
                    }}
                  >
                    Download print PDF
                  </button>
                </>
              ) : (
                <p role={pdfError ? "alert" : "status"}>
                  {pdfError || "Preparing your print file…"}
                </p>
              )}
            </>
          )}
          <Feedback {...action} />
        </DialogContent>
      </Dialog>
      <Dialog open={sharing} onOpenChange={setSharing}>
        <DialogContent
          className="cx-app mm-dialog mm-sharing-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>Your published menu</DialogTitle>
          <MenuSharing
            restaurant={state.restaurant}
            busy={!!busy}
            act={act}
            refresh={refresh}
            notice={setNotice}
          />
          <Feedback {...action} />
        </DialogContent>
      </Dialog>
      <Dialog open={batchOpen} onOpenChange={setBatchOpen}>
        <DialogContent
          className="cx-app mm-dialog mm-batch-dialog"
          aria-describedby={undefined}
        >
          <DialogTitle>Prepare a consistent set of photos</DialogTitle>
          <div className="cx-batch-layout">
            <div className="cx-menu-photo-list">
              {rows.map((r) => {
                const original = state.assets.find(
                    (a: Row) => a.dish_id === r.id && a.kind === "source",
                  ),
                  approved = state.assets.find(
                    (a: Row) => a.dish_id === r.id && a.approved_at,
                  );
                return (
                  <article key={r.rowId}>
                    {r.photoId || approved ? (
                      <img
                        src={`/api/assets/${r.photoId || approved?.id}`}
                        alt={r.name}
                      />
                    ) : original ? (
                      <img src={`/api/assets/${original.id}`} alt={r.name} />
                    ) : (
                      <span className="cx-photo-empty">
                        <BookOpen size={22} />
                      </span>
                    )}
                    <div>
                      <b>{r.name}</b>
                      <small>
                        {approved
                          ? "Approved photo available"
                          : original
                            ? "Original photo saved"
                            : "Text-only dish"}
                      </small>
                      {approved && r.photoId !== approved.id && (
                        <button
                          className="cx-link"
                          onClick={() =>
                            change({
                              rows: rows.map((x) =>
                                x.id === r.id
                                  ? { ...x, photoId: approved.id }
                                  : x,
                              ),
                            })
                          }
                        >
                          Use approved photo in this menu
                        </button>
                      )}
                    </div>
                    {original ? (
                      <label className="cx-check">
                        <input
                          aria-label={`Improve ${r.name}`}
                          type="checkbox"
                          checked={b.batchSelected.includes(r.id)}
                          disabled={!!b.batch}
                          onChange={(e) =>
                            change({
                              batchSelected: e.target.checked
                                ? [...b.batchSelected, r.id]
                                : b.batchSelected.filter(
                                    (id: string) => id !== r.id,
                                  ),
                            })
                          }
                        />
                        Improve
                      </label>
                    ) : (
                      <button className="cx-link" onClick={() => onPhoto(r.id)}>
                        Add photo <ArrowRight size={15} />
                      </button>
                    )}
                  </article>
                );
              })}
            </div>
            <aside className="cx-panel">
              <span className="cx-pill">
                <Sparkles size={14} />
                Try one, then the rest
              </span>
              <h2>A consistent look, without the guesswork.</h2>
              <p>
                Select up to five dishes. Create the first photo, approve its
                look, then apply it to the remaining dishes.
              </p>
              {!b.batch ? (
                <>
                  <Field label="The look for this batch">
                    <select
                      value={b.batchLook}
                      onChange={(e) => change({ batchLook: e.target.value })}
                    >
                      {looks
                        .filter(
                          (l) =>
                            l.id !== "reference" &&
                            (!l.legacy || l.id === b.batchLook),
                        )
                        .map((l) => (
                          <option key={l.id} value={l.id}>
                            {l.group} · {l.name}
                          </option>
                        ))}
                    </select>
                  </Field>
                  <button
                    className="cx-btn cx-full"
                    disabled={
                      !!busy ||
                      b.batchSelected.length < 1 ||
                      b.batchSelected.length > 5 ||
                      !state.aiConnected ||
                      state.remaining < 1
                    }
                    onClick={() =>
                      act("Creating your first batch photo", startBatch)
                    }
                  >
                    Create first photo · 1 image
                  </button>
                  <small>
                    {b.batchSelected.length} selected ·{" "}
                    {Math.max(0, b.batchSelected.length - 1)} will wait for your
                    approval
                  </small>
                  {!state.aiConnected && (
                    <p className="cx-hint">
                      Image creation is awaiting its service connection. You can
                      continue with approved photos or a text-only menu.
                    </p>
                  )}
                </>
              ) : (
                <>
                  <h3>
                    {sampleAsset?.approved_at
                      ? "First photo approved"
                      : sampleOutput
                        ? "Review your first photo"
                        : sampleJob?.status === "failed"
                          ? "First photo needs attention"
                          : "Creating your first photo…"}
                  </h3>
                  {sampleOutput && (
                    <button
                      className="cx-sample-photo"
                      onClick={() =>
                        onPhoto(b.batch.items[0].dishId, sampleOutput.asset_id)
                      }
                    >
                      <img
                        src={`/api/assets/${sampleOutput.asset_id}`}
                        alt="First photo in your selected batch"
                      />
                      <span>
                        {sampleAsset?.approved_at
                          ? "View approved photo"
                          : "Review & approve this photo"}{" "}
                        <ArrowRight size={15} />
                      </span>
                    </button>
                  )}
                  {sampleJob?.status === "failed" && (
                    <button
                      className="cx-link"
                      disabled={!!busy}
                      onClick={() =>
                        act("Retrying the first photo", async () => {
                          await api(
                            `photo-batches/${b.batchId}/retry-sample`,
                            {},
                          );
                          await refresh();
                          void api("jobs/tick", {})
                            .then(refresh)
                            .catch(() => {});
                        })
                      }
                    >
                      Retry first photo · 1 image
                    </button>
                  )}
                  {!b.batch.continued && b.batch.items.length > 1 && (
                    <button
                      className="cx-btn cx-full"
                      disabled={
                        !!busy ||
                        !sampleAsset?.approved_at ||
                        state.remaining < b.batch.items.length - 1
                      }
                      onClick={() =>
                        act("Creating the remaining photos", async () => {
                          await api(`photo-batches/${b.batchId}/continue`, {
                            remainingCount: b.batch.items.length - 1,
                          });
                          change({ batch: { ...b.batch, continued: true } });
                          await save();
                          await refresh();
                        })
                      }
                    >
                      Apply to remaining {b.batch.items.length - 1} ·{" "}
                      {b.batch.items.length - 1} images
                    </button>
                  )}
                  {b.batch.continued && (
                    <p className="cx-hint">
                      The remaining selected dishes are in progress. Successful
                      photos stay saved.
                    </p>
                  )}
                  {state.batchItems
                    .filter((i: Row) => i.batch_id === b.batchId)
                    .map((i: Row) => (
                      <div key={i.id} className="cx-batch-status">
                        <span>
                          {rows.find((r) => r.id === i.dish_id)?.name} ·{" "}
                          {i.job_status || i.status}
                        </span>
                        {i.status === "failed" ||
                        i.job_status === "failed" ||
                        i.job_status === "partial" ? (
                          <button
                            className="cx-link"
                            disabled={!!busy}
                            onClick={() =>
                              act("Retrying only failed photos", async () => {
                                await api("batches/retry", { id: i.id });
                                await refresh();
                              })
                            }
                          >
                            Retry failed
                          </button>
                        ) : null}
                        {state.outputs.find(
                          (o: Row) => o.job_id === i.job_id && o.asset_id,
                        ) && (
                          <button
                            className="cx-link"
                            onClick={() =>
                              onPhoto(
                                i.dish_id,
                                state.outputs.find(
                                  (o: Row) =>
                                    o.job_id === i.job_id && o.asset_id,
                                ).asset_id,
                              )
                            }
                          >
                            Review photo
                          </button>
                        )}
                      </div>
                    ))}
                  <button
                    className="cx-link"
                    onClick={() => {
                      batchKey.current = "";
                      change({ batch: null, batchId: "", batchSelected: [] });
                    }}
                  >
                    Choose another group
                  </button>
                </>
              )}
            </aside>
          </div>

          <Feedback {...action} />
        </DialogContent>
      </Dialog>
    </section>
  );
}

"use client";
import { useCallback, useEffect, useId, useRef, useState } from "react";
import type { Row } from "@/lib/client";
import { scheduleLabel } from "@/lib/promotions";
import {
  entryPrice,
  menuPrice,
  visibleMenuSections,
  type DesignedMenu,
} from "@/lib/menu-document";
import {
  menuDesignSpec,
  menuFontFamilies,
  menuTheme,
} from "@/lib/menu-design-system";
import MenuPhoto from "./menu-photo";
import CustomerMenuSwitcher from "./customer-menu-switcher";
import { ChevronLeft, ChevronRight } from "lucide-react";

type GuestMenu = DesignedMenu & {
  menus?: { id: string; name: string }[];
  specials?: Row[];
  serverNow?: number;
};
export default function MenuDocumentView({
  menu: initial,
  preview = false,
  slug,
  onSelect,
}: {
  menu: GuestMenu;
  preview?: boolean;
  slug?: string;
  onSelect?: (id: string) => void;
}) {
  const [live, setLive] = useState(initial),
    [search, setSearch] = useState(""),
    [sectionTarget, setSectionTarget] = useState<{ id: string } | null>(null),
    [activeSection, setActiveSection] = useState(""),
    [sectionsOverflow, setSectionsOverflow] = useState(false),
    [sectionsAtEnd, setSectionsAtEnd] = useState(false),
    [unavailable, setUnavailable] = useState(false),
    [time, setTime] = useState(initial.serverNow || 0);
  const root = useRef<HTMLElement>(null),
    sectionLinks = useRef<HTMLDivElement>(null),
    session = useRef("");
  const menuId = useId();
  const menu = preview ? initial : live,
    theme = menuTheme(menu),
    spec = menuDesignSpec(menu.design),
    sections = visibleMenuSections(menu);
  const query = search.trim();
  const hero =
    menu.layout === "featured"
      ? sections
          .flatMap((s) => s.items)
          .find((i) => i.featured && i.photoId && i.available)
      : undefined;
  const asset = (id: string) =>
    slug && !preview ? `/api/public/${slug}/assets/${id}` : `/api/assets/${id}`;
  const track = useCallback(
    (kind: string, entityId?: string) => {
      if (preview || !slug || !session.current) return;
      void fetch(
        `/api/public/${slug}/events${menu.documentId ? `?menu=${menu.documentId}` : ""}`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ kind, entityId, session: session.current }),
          keepalive: true,
        },
      ).catch(() => {});
    },
    [preview, slug, menu.documentId],
  );
  useEffect(() => {
    if (!sectionTarget) return;
    // Wait for the cleared search to render before moving keyboard focus.
    const heading = root.current?.querySelector<HTMLElement>(
      `[data-section="${CSS.escape(sectionTarget.id)}"] h2`,
    );
    heading?.focus({ preventScroll: true });
    heading?.scrollIntoView({
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "instant"
        : "smooth",
      block: "start",
    });
  }, [sectionTarget]);
  useEffect(() => {
    const list = sectionLinks.current;
    if (!list) return;
    const measure = () => {
      setSectionsOverflow(list.scrollWidth > list.clientWidth + 2);
      setSectionsAtEnd(
        list.scrollLeft + list.clientWidth >= list.scrollWidth - 2,
      );
    };
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    const frame = requestAnimationFrame(measure);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [menu.sections]);
  useEffect(() => {
    if (preview || !root.current) return;
    const targets = Array.from(
      root.current.querySelectorAll<HTMLElement>("[data-section]"),
    );
    let frame = 0;
    const measure = () => {
      frame = 0;
      const atEnd =
        window.scrollY + window.innerHeight >=
        document.documentElement.scrollHeight - 2;
      const current = atEnd
        ? targets.at(-1)
        : targets
            .filter(
              (target) =>
                target.getBoundingClientRect().top <= window.innerHeight * 0.25,
            )
            .at(-1) || targets[0];
      if (current) setActiveSection(current.dataset.section || "");
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    schedule();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, [menu.sections, preview, query]);
  useEffect(() => {
    if (preview || !live.specials?.length) return;
    const local = Date.now(),
      server = live.serverNow || local;
    const timer = setInterval(() => setTime(server + Date.now() - local), 1000);
    return () => clearInterval(timer);
  }, [preview, live]);
  useEffect(() => {
    if (preview || !slug) return;
    try {
      const key = `menu-session:${slug}`;
      session.current = sessionStorage.getItem(key) || crypto.randomUUID();
      sessionStorage.setItem(key, session.current);
    } catch {
      session.current = crypto.randomUUID();
    }
    track("menu_visit");
    const requestedMenu = new URLSearchParams(location.search).get("menu");
    const refresh = async () => {
      if (document.hidden) return;
      try {
        const res = await fetch(
          `/api/public/${slug}${requestedMenu ? `?menu=${encodeURIComponent(requestedMenu)}` : ""}`,
          { cache: "no-store" },
        );
        if (res.status === 404) {
          setUnavailable(true);
          return;
        }
        if (res.ok) {
          const data = (await res.json()) as { menu: GuestMenu };
          setLive(data.menu);
          setUnavailable(false);
        }
      } catch {
        /* Keep the most recent menu during a temporary connection failure. */
      }
    };
    const timer = setInterval(refresh, 20000);
    document.addEventListener("visibilitychange", refresh);
    return () => {
      clearInterval(timer);
      document.removeEventListener("visibilitychange", refresh);
    };
  }, [slug, initial.documentId, preview, track]);
  useEffect(() => {
    if (preview || !slug || !root.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        for (const e of entries)
          if (e.isIntersecting) {
            track("dish_view", (e.target as HTMLElement).dataset.entry);
            observer.unobserve(e.target);
          }
      },
      { threshold: 0.5 },
    );
    root.current
      .querySelectorAll("[data-entry]")
      .forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [live, preview, slug, track]);
  if (unavailable)
    return (
      <main className="unavailable">
        <h1>This menu isn’t available right now.</h1>
        <p>Please check with the restaurant.</p>
        {slug && <a href={`/m/${slug}`}>View the restaurant’s current menu</a>}
      </main>
    );
  const filtered = sections
    .map((s) => ({
      ...s,
      items: s.items.filter((i) =>
        `${s.name} ${i.name} ${i.description} ${i.dietary.join(" ")}`
          .toLocaleLowerCase(menu.language)
          .includes(query.toLocaleLowerCase(menu.language)),
      ),
    }))
    .filter((s) => s.items.length);
  const resultCount = filtered.reduce((n, s) => n + s.items.length, 0);
  const Surface = preview ? "article" : "main";
  return (
    <Surface
      ref={root}
      className={`md-guest md-design-${menu.design} md-density-${menu.density} ${onSelect ? "md-editable" : ""}`}
      lang={menu.language}
      aria-label={`${menu.restaurant.name} ${menu.title}`}
      style={
        {
          "--md-paper": theme.background,
          "--md-ink": theme.ink,
          "--md-muted": theme.muted,
          "--md-accent": theme.accent,
          "--md-rule": theme.rule,
          "--md-subtle": theme.subtle,
          "--md-on-accent": theme.onAccent,
          "--md-heading": menuFontFamilies[spec.heading],
          "--md-item": menuFontFamilies[spec.item],
        } as React.CSSProperties
      }
    >
      <header className={`md-guest-header ${hero ? "has-photo" : ""}`}>
        {menu.showLogo &&
          (menu.restaurant.logoId || menu.restaurant.logo_id) && (
            <img
              className="md-guest-logo"
              src={asset((menu.restaurant.logoId || menu.restaurant.logo_id)!)}
              alt={`${menu.restaurant.name} logo`}
            />
          )}
        <h1>{menu.restaurant.name}</h1>
        <p className="md-guest-title">{menu.title}</p>
        {menu.subtitle && <p className="md-guest-intro">{menu.subtitle}</p>}
        {menu.fixedPrice != null && (
          <p className="md-guest-fixed">
            {menuPrice(
              menu.fixedPrice,
              menu.restaurant.currency,
              menu.priceFormat,
              menu.language,
            )}{" "}
            <span>{menu.fixedPriceLabel}</span>
          </p>
        )}
        {hero?.photoId && (
          <div className="md-guest-hero">
            <MenuPhoto
              photoId={hero.photoId}
              crop={hero.crop}
              alt={hero.name}
              featured
              priority
              slug={preview ? undefined : slug}
            />
            <span>{hero.name}</span>
            {onSelect && (
              <button
                className="md-item-select"
                aria-label={`Edit ${hero.name}`}
                onClick={() => onSelect(hero.id)}
              />
            )}
          </div>
        )}
        {!preview && menu.restaurant.orderingUrl && (
          <a
            className="md-order"
            href={menu.restaurant.orderingUrl}
            onClick={() => track("ordering_click")}
          >
            Order online
          </a>
        )}
      </header>
      {!preview && !!menu.menus && menu.menus.length > 1 && (
        <CustomerMenuSwitcher
          menus={menu.menus}
          currentId={menu.documentId}
          slug={slug!}
          className="md-menu-switcher"
        />
      )}
      {(sections.length > 3 ||
        sections.reduce((n, s) => n + s.items.length, 0) > 12) && (
        <nav className="md-guest-nav" aria-label="Find a menu item">
          <input
            type="search"
            aria-label="Search this menu"
            placeholder="Search the menu…"
            aria-controls={`${menuId}-items`}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <div className="md-section-navigation">
            <div
              className="md-section-links"
              ref={sectionLinks}
              onScroll={(event) => {
                const list = event.currentTarget;
                setSectionsAtEnd(
                  list.scrollLeft + list.clientWidth >= list.scrollWidth - 2,
                );
              }}
            >
              {sections.map((s) => (
                <button
                  key={s.id}
                  aria-current={
                    (activeSection || sections[0]?.id) === s.id
                      ? "location"
                      : undefined
                  }
                  aria-controls={
                    filtered.some((section) => section.id === s.id)
                      ? `${menuId}-${s.id}`
                      : undefined
                  }
                  onClick={() => {
                    setSearch("");
                    setActiveSection(s.id);
                    setSectionTarget({ id: s.id });
                  }}
                >
                  {s.name}
                </button>
              ))}
            </div>
            {sectionsOverflow && (
              <button
                className="md-sections-more"
                aria-label={
                  sectionsAtEnd
                    ? "Back to first sections"
                    : "Show more sections"
                }
                onClick={() => {
                  const list = sectionLinks.current;
                  if (!list) return;
                  const behavior = matchMedia(
                    "(prefers-reduced-motion: reduce)",
                  ).matches
                    ? "instant"
                    : "smooth";
                  if (sectionsAtEnd) list.scrollTo({ left: 0, behavior });
                  else
                    list.scrollBy({ left: list.clientWidth * 0.8, behavior });
                }}
              >
                {sectionsAtEnd ? (
                  <ChevronLeft size={18} />
                ) : (
                  <ChevronRight size={18} />
                )}
              </button>
            )}
          </div>
          <p
            className="md-guest-search-status"
            role="status"
            aria-atomic="true"
          >
            {query
              ? `${resultCount} ${resultCount === 1 ? "item matches" : "items match"} “${query}”.`
              : `All ${resultCount} items shown.`}
          </p>
        </nav>
      )}
      {!preview && !!menu.specials?.length && (
        <div className="md-guest-specials">
          {menu.specials
            .filter((s) => !s.endsAt || s.endsAt > time)
            .map((s) => (
              <section key={s.id}>
                <span>Special offer</span>
                <div>
                  <h2>{s.title}</h2>
                  <strong>
                    {menuPrice(
                      s.price,
                      menu.restaurant.currency,
                      menu.priceFormat,
                      menu.language,
                    )}
                  </strong>
                </div>
                <p>{s.description}</p>
                <div className="md-special-photos">
                  {s.items.map((i: Row) => (
                    <figure data-entry={i.dishId} key={i.dishId}>
                      <img
                        src={asset(i.photoId)}
                        alt={i.name}
                        loading="lazy"
                        decoding="async"
                      />
                      <figcaption>
                        {i.quantity} × {i.name}
                      </figcaption>
                    </figure>
                  ))}
                </div>
                <small>{scheduleLabel(s.startsAt, s.endsAt, s.timezone)}</small>
              </section>
            ))}
        </div>
      )}
      <div className="md-guest-sections" id={`${menuId}-items`}>
        {filtered.map((section) => (
          <section key={section.id} data-section={section.id}>
            <header>
              <h2 id={`${menuId}-${section.id}`} tabIndex={-1}>
                {section.name}
              </h2>
              {section.description && <p>{section.description}</p>}
            </header>
            <div>
              {section.items.map((item) => (
                <div
                  className={`md-guest-item ${!item.available ? "is-unavailable" : ""}`}
                  data-entry={item.id}
                  key={item.id}
                >
                  {item.photoId &&
                    item.photoId !== hero?.photoId &&
                    (menu.layout === "grid" ||
                      (menu.layout === "featured" && item.featured)) && (
                      <MenuPhoto
                        photoId={item.photoId}
                        crop={item.crop}
                        alt={item.name}
                        slug={preview ? undefined : slug}
                        featured
                      />
                    )}
                  <div
                    className="md-guest-item-title"
                    data-price-mode={item.priceMode}
                  >
                    <h3>{item.name || "Untitled dish"}</h3>
                    {entryPrice(item, menu) && (
                      <span>{entryPrice(item, menu)}</span>
                    )}
                  </div>
                  {item.description && <p>{item.description}</p>}
                  {!!item.variants.length && item.priceMode === "variants" && (
                    <dl
                      className="md-guest-prices"
                      data-options={item.variants.length}
                    >
                      {item.variants.map((v) => (
                        <div key={v.id}>
                          <dt>{v.label}</dt>
                          <dd>
                            {menuPrice(
                              v.price,
                              menu.restaurant.currency,
                              menu.priceFormat,
                              menu.language,
                            )}
                          </dd>
                        </div>
                      ))}
                    </dl>
                  )}
                  {!!item.additions.length && (
                    <dl className="md-guest-additions">
                      {item.additions.map((v) => (
                        <div key={v.id}>
                          <dt>+ {v.label}</dt>
                          <dd>
                            {menuPrice(
                              v.price,
                              menu.restaurant.currency,
                              menu.priceFormat,
                              menu.language,
                            )}
                          </dd>
                        </div>
                      ))}
                    </dl>
                  )}
                  {!!item.dietary.length && (
                    <p className="md-guest-dietary">
                      {item.dietary.join(" · ")}
                    </p>
                  )}
                  {!item.available && (
                    <p className="md-guest-unavailable">
                      Currently unavailable
                    </p>
                  )}
                  {onSelect && (
                    <button
                      className="md-item-select"
                      aria-label={`Edit ${item.name || "dish"}`}
                      onClick={() => onSelect(item.id)}
                    />
                  )}
                </div>
              ))}
            </div>
          </section>
        ))}
      </div>
      {!filtered.length && (
        <p className="md-guest-empty">
          {query
            ? `No menu items match “${query}”.`
            : "Your dishes will appear here."}
        </p>
      )}
      {menu.footer && (
        <footer className="md-guest-footer">{menu.footer}</footer>
      )}
      {!preview && (
        <div className="md-guest-credit">Made with Menu Material</div>
      )}
    </Surface>
  );
}

import { menuCrop } from "@/lib/menu-design";
import type { Row } from "@/lib/client";
/** CSS object positioning and PDF drawPhoto use the same normalized frame. */
export default function MenuPhoto({
  photoId,
  crop,
  featured = false,
  slug,
  alt = "",
  priority = false,
}: {
  photoId: string;
  crop?: Row;
  featured?: boolean;
  slug?: string;
  alt?: string;
  priority?: boolean;
}) {
  const frame = menuCrop(crop);
  return (
    <div className={`mm-menu-photo ${featured ? "is-featured" : ""}`}>
      <img
        src={
          slug
            ? `/api/public/${slug}/assets/${photoId}`
            : `/api/assets/${photoId}`
        }
        alt={alt}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        style={{
          objectFit: frame.fit ? "contain" : "cover",
          objectPosition: `${frame.x}% ${frame.y}%`,
          transform: `scale(${frame.zoom})`,
          transformOrigin: `${frame.x}% ${frame.y}%`,
        }}
      />
    </div>
  );
}

