}
export function MoneyInput({
  value,
  onChange,
  label,
  ...inputProps
}: {
  value: number | null;
  onChange: (v: number | null) => void;
  label?: string;
  id?: string;
  "aria-describedby"?: string;
}) {
  const [raw, setRaw] = useState(value == null ? "" : (value / 100).toFixed(2)),
    focus = useRef(false);
  useEffect(() => {
    if (!focus.current) setRaw(value == null ? "" : (value / 100).toFixed(2));
  }, [value]);
  return (
    <input
      {...inputProps}
      aria-label={label}
      inputMode="decimal"
      placeholder="0.00"
      value={raw}
      onFocus={() => {
        focus.current = true;
      }}
      onChange={(e) => {
        const next = e.target.value;
        if (!/^\d{0,7}([.,]\d{0,2})?$/.test(next)) return;
        setRaw(next);
        const n = Number(next.replace(",", "."));
        onChange(
          next && Number.isFinite(n)
            ? Math.min(100000000, Math.round(n * 100))
            : null,
        );
      }}
      onBlur={() => {
        focus.current = false;
        setRaw(value == null ? "" : (value / 100).toFixed(2));
      }}
    />
  );
}
