}
function LegacyMenuView({
  menu: initialMenu,
  slug,
  preview = false,
  serverNow = 0,
  onSelect,
}: {
  menu: Row;
  slug?: string;
  preview?: boolean;
  serverNow?: number;
  onSelect?: (dishId: string) => void;
}) {
  const [search, setSearch] = useState("");
  const [sectionTarget, setSectionTarget] = useState<{ index: number } | null>(
      null,
    ),
    [activeSection, setActiveSection] = useState("0"),
    [sectionsOverflow, setSectionsOverflow] = useState(false),
    [sectionsAtEnd, setSectionsAtEnd] = useState(false);
  const [liveMenu, setMenu] = useState(initialMenu),
    [time, setTime] = useState(serverNow),
    [unavailable, setUnavailable] = useState(false);
  const serverClock = useRef({ server: serverNow, local: 0 }),
    article = useRef<HTMLElement>(null),
    sectionLinks = useRef<HTMLDivElement>(null),
    session = useRef("");
  const menu = preview ? initialMenu : liveMenu;
  const hero = menuHero(menu);
  useEffect(() => {
    if (!sectionTarget) return;
    const heading = article.current?.querySelector<HTMLElement>(
      `[data-menu-section="${sectionTarget.index}"] h2`,
    );
    heading?.focus({ preventScroll: true });
    heading?.scrollIntoView({
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "instant"
        : "smooth",
      block: "start",
    });
  }, [sectionTarget]);
  useEffect(() => {
    const list = sectionLinks.current;
    if (!list) return;
    const measure = () => {
      setSectionsOverflow(list.scrollWidth > list.clientWidth + 2);
      setSectionsAtEnd(
        list.scrollLeft + list.clientWidth >= list.scrollWidth - 2,
      );
    };
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    const frame = requestAnimationFrame(measure);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [menu.sections]);
  useEffect(() => {
    if (preview || !article.current) return;
    const targets = Array.from(
      article.current.querySelectorAll<HTMLElement>("[data-menu-section]"),
    );
    let frame = 0;
    const measure = () => {
      frame = 0;
      const atEnd =
        window.scrollY + window.innerHeight >=
        document.documentElement.scrollHeight - 2;
      const current = atEnd
        ? targets.at(-1)
        : targets
            .filter(
              (target) =>
                target.getBoundingClientRect().top <= window.innerHeight * 0.25,
            )
            .at(-1) || targets[0];
      if (current) setActiveSection(current.dataset.menuSection || "0");
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    schedule();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, [menu.sections, search, preview]);
  const track = useCallback(
    (kind: string, entityId?: string) => {
      if (preview || !slug || !session.current) return;
      void fetch(`/api/public/${slug}/events`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ kind, entityId, session: session.current }),
        keepalive: true,
      }).catch(() => {});
    },
    [preview, slug],
  );
  useEffect(() => {
    if (preview || !slug || menu.version === 2) return;
    try {
      session.current =
        sessionStorage.getItem("menu-session:" + slug) || crypto.randomUUID();
      sessionStorage.setItem("menu-session:" + slug, session.current);
    } catch {
      session.current = crypto.randomUUID();
    }
    serverClock.current.local = Date.now();
    track("menu_visit");
    const clock = setInterval(
      () =>
        setTime(
          serverClock.current.server + Date.now() - serverClock.current.local,
        ),
      1000,
    );
    const refresh = async () => {
      if (document.hidden) return;
      try {
        const selected = new URLSearchParams(location.search).get("menu");
        const res = await fetch(
          "/api/public/" +
            slug +
            (selected ? `?menu=${encodeURIComponent(selected)}` : ""),
          { cache: "no-store" },
        );
        if (res.status === 404) {
          setUnavailable(true);
          return;
        }
        if (!res.ok) return;
        const data = (await res.json()) as Row;
        serverClock.current = { server: data.serverNow, local: Date.now() };
        setTime(data.serverNow);
        setMenu(data.menu);
        setUnavailable(false);
      } catch {}
    };
    const interval = setInterval(refresh, 20000);
    const visible = () => {
      if (!document.hidden) void refresh();
    };
    document.addEventListener("visibilitychange", visible);
    return () => {
      clearInterval(clock);
      clearInterval(interval);
      document.removeEventListener("visibilitychange", visible);
    };
  }, [slug, preview, track, menu.version]);
  useEffect(() => {
    if (preview || !slug || !article.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries)
          if (entry.isIntersecting) {
            track("dish_view", (entry.target as HTMLElement).dataset.dish);
            observer.unobserve(entry.target);
          }
      },
      { threshold: 0.5 },
    );
    article.current
      .querySelectorAll("[data-dish]")
      .forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [menu, preview, slug, track]);
  if (unavailable)
    return (
      <main className="unavailable">
        <h1>This menu isn’t available right now.</h1>
        <p>Please check with the restaurant.</p>
      </main>
    );
  if (menu.version === 2)
    return (
      <MenuDocumentView
        menu={menu as DesignedMenu}
        slug={slug}
        preview={preview}
        onSelect={onSelect}
      />
    );
  return (
    <article
      role={preview ? undefined : "main"}
      aria-label={preview ? undefined : `${menu.restaurant.name} menu`}
      className={`customer-menu menu-designed menu-art-directed menu-design-${menu.design || "bistro"} menu-density-${menu.density || "comfortable"} menu-layout-${menu.layout || "classic"} menu-appearance-${menuAppearance(menu)}`}
      style={
        {
          "--menu-brand":
            readableBrandInk(menu.restaurant.style?.primary || "#235b48") ===
            "#ffffff"
              ? menu.restaurant.style?.primary || "#235b48"
              : "#203b2c",
          "--menu-accent": menu.restaurant.style?.accent || "#f0e3c3",
          "--menu-accent-ink": readableBrandInk(
            menu.restaurant.style?.accent || "#f0e3c3",
          ),
          "--menu-heading-font": `"${brandTypeface(menu.restaurant.style).family}"`,
        } as React.CSSProperties
      }
      ref={article}
    >
      <header className={hero ? "has-hero" : ""}>
        {hero && (
          <div className="menu-hero-photo">
            <MenuPhoto
              photoId={hero.photoId}
              crop={hero.crop}
              featured
              priority
              slug={preview ? undefined : slug}
              alt={hero.name}
            />
            {onSelect && (
              <button
                className="mm-menu-edit-target"
                aria-label={`Edit ${hero.name}`}
                onClick={() => onSelect(hero.id)}
              />
            )}
          </div>
        )}
        <div className="menu-identity">
          {menu.restaurant.logoId ? (
            <img
              className="menu-logo"
              src={
                preview
                  ? `/api/assets/${menu.restaurant.logoId}`
                  : `/api/public/${slug}/assets/${menu.restaurant.logoId}`
              }
              alt="Restaurant logo"
            />
          ) : null}
          {!menu.restaurant.logoId && (
            <span className="menu-monogram" aria-hidden="true">
              {String(menu.restaurant.name)
                .split(/\s+/)
                .filter((w: string) => /[a-z]/i.test(w))
                .slice(0, 2)
                .map((w: string) => w[0])
                .join("")}
            </span>
          )}
          <h1>{menu.restaurant.name}</h1>
          <p>{menu.title || menu.restaurant.cuisine}</p>
          {menu.restaurant.orderingUrl && (
            <a
              className="order-button"
              href={menu.restaurant.orderingUrl}
              onClick={() => track("ordering_click")}
              rel="noreferrer"
            >
              Order from {menu.restaurant.name}
            </a>
          )}
        </div>
        {hero && (
          <div className="menu-hero-caption">
            <span>{hero.name}</span>
            <span>
              {Number.isFinite(hero.price)
                ? money(hero.price, menu.restaurant.currency)
                : ""}
            </span>
          </div>
        )}
      </header>
      {!preview && menu.menus?.length > 1 && (
        <CustomerMenuSwitcher
          menus={menu.menus}
          currentId={
            menu.documentId || menu.menus.find((m: Row) => m.isPrimary)?.id
          }
          slug={slug!}
          className="menu-document-switcher"
        />
      )}
      {(menu.sections.length > 3 ||
        menu.sections.reduce((n: number, s: Row) => n + s.items.length, 0) >
          12) && (
        <nav className="mm-guest-nav" aria-label="Find a dish">
          <input
            aria-label="Search menu"
            type="search"
            placeholder="Find a dish…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <div className="mm-guest-section-navigation">
            <div
              className="mm-guest-section-links"
              ref={sectionLinks}
              onScroll={(event) => {
                const list = event.currentTarget;
                setSectionsAtEnd(
                  list.scrollLeft + list.clientWidth >= list.scrollWidth - 2,
                );
              }}
            >
              {menu.sections.map((s: Row, n: number) => (
                <button
                  key={s.id}
                  aria-current={
                    activeSection === String(n) ? "location" : undefined
                  }
                  onClick={() => {
                    setSearch("");
                    setActiveSection(String(n));
                    setSectionTarget({ index: n });
                  }}
                >
                  {s.name}
                </button>
              ))}
            </div>
            {sectionsOverflow && (
              <button
                className="mm-guest-sections-more"
                aria-label={
                  sectionsAtEnd
                    ? "Back to first sections"
                    : "Show more sections"
                }
                onClick={() => {
                  const list = sectionLinks.current;
                  if (!list) return;
                  const behavior = matchMedia(
                    "(prefers-reduced-motion: reduce)",
                  ).matches
                    ? "instant"
                    : "smooth";
                  if (sectionsAtEnd) list.scrollTo({ left: 0, behavior });
                  else
                    list.scrollBy({ left: list.clientWidth * 0.8, behavior });
                }}
              >
                {sectionsAtEnd ? (
                  <ChevronLeft size={18} />
                ) : (
                  <ChevronRight size={18} />
                )}
              </button>
            )}
          </div>
        </nav>
      )}
      {(menu.specials || [])
        .filter((s: Row) => !s.endsAt || s.endsAt > time)
        .map((special: Row) => (
          <section className="customer-special" key={special.id}>
            <p className="eyebrow">SPECIAL OFFER</p>
            <div className="dish-title">
              <h2>{special.title}</h2>
              <b>{money(special.price, menu.restaurant.currency)}</b>
            </div>
            <p>{special.description}</p>
            <div className="customer-special-photos">
              {special.items.map((item: Row) => (
                <figure key={item.dishId} data-dish={item.dishId}>
                  <img
                    src={
                      preview
                        ? `/api/assets/${item.photoId}`
                        : `/api/public/${slug}/assets/${item.photoId}`
                    }
                    alt={item.name}
                    loading="lazy"
                    decoding="async"
                  />
                  <figcaption>
                    {item.quantity} × {item.name}
                  </figcaption>
                </figure>
              ))}
            </div>
            <p className="fine">
              {scheduleLabel(
                special.startsAt,
                special.endsAt,
                special.timezone,
              )}
            </p>
          </section>
        ))}
      <div className="menu-sections">
        {menu.sections.map((section: Row, sectionIndex: number) => {
          const dishes = section.items.filter((d: Row) =>
            `${d.name} ${d.description || ""} ${section.name}`
              .toLowerCase()
              .includes(search.toLowerCase()),
          );
          return (
            !!dishes.length && (
              <section key={section.id} data-menu-section={sectionIndex}>
                <header className="menu-section-heading">
                  <span aria-hidden="true">
                    {String(sectionIndex + 1).padStart(2, "0")}
                  </span>
                  <h2 tabIndex={-1}>{section.name}</h2>
                </header>
                <div className="menu-section-body">
                  {dishes.map((dish: Row, index: number) => {
                    const featured =
                      menu.layout === "featured" &&
                      (dish.featured ?? section.items[0] === dish);
                    return (
                      <div
                        className={`customer-dish ${!dish.available ? "sold-out" : ""} ${featured ? "is-featured" : ""} ${onSelect ? "is-editable" : ""}`}
                        key={dish.id + index}
                        data-dish={dish.id}
                      >
                        <div className="mm-menu-dish-copy">
                          <div className="dish-title">
                            <h3>{dish.name}</h3>
                            <span>
                              {Number.isFinite(dish.price)
                                ? money(dish.price, menu.restaurant.currency)
                                : "—"}
                            </span>
                          </div>
                          {dish.description && <p>{dish.description}</p>}
                          {!dish.available && (
                            <span className="tag">Currently unavailable</span>
                          )}
                        </div>
                        {dish.photoId &&
                          dish.photoId !== hero?.photoId &&
                          (menu.layout === "grid" || featured) && (
                            <MenuPhoto
                              photoId={dish.photoId}
                              crop={dish.crop}
                              featured={featured}
                              slug={preview ? undefined : slug}
                              alt={dish.name}
                            />
                          )}
                        {onSelect && (
                          <button
                            className="mm-menu-edit-target"
                            aria-label={`Edit ${dish.name}`}
                            onClick={() => onSelect(dish.id)}
                          />
                        )}
                      </div>
                    );
                  })}
                </div>
              </section>
            )
          );
        })}
      </div>
      {search &&
        !menu.sections.some((s: Row) =>
          s.items.some((d: Row) =>
            `${d.name} ${d.description || ""} ${s.name}`
              .toLowerCase()
              .includes(search.toLowerCase()),
          ),
        ) && <p className="mm-menu-no-results">No dishes match “{search}”.</p>}
      <footer>Made with Menu Material</footer>
    </article>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { api, downloadBlob, type Row } from "@/lib/client";
import { recipeFromDraft } from "@/lib/studio-library";
import { styleFor } from "@/lib/studio";
import { masterPhotoExport } from "@/lib/photo-export";
import { photoFilename } from "@/lib/photo-destinations";
import { track } from "./creation-shared";

export function PhotoBatchSheet({
  state,
  draft,
  onClose,
  remember,
  onReview,
  refresh,
  onCloseAutoFocus,
}: {
  state: Row;
  draft: Row;
  onClose: () => void;
  remember: (id: string) => Promise<void>;
  onReview: (item: Row, jobId: string, assetId: string) => void;
  refresh: () => Promise<void>;
  onCloseAutoFocus: (event: Event) => void;
}) {
  const [selected, setSelected] = useState<string[]>([]),
    [batch, setBatch] = useState<Row | null>(null),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(""),
    [notice, setNotice] = useState("");
  const [included, setIncluded] = useState<string[]>([]);
  const batchId = useRef(draft.photoBatchId || crypto.randomUUID()),
    lock = useRef(false);
  useEffect(() => {
    let active = true;
    if (draft.photoBatchId && !lock.current)
      api(`photo-batches/${draft.photoBatchId}`)
        .then(({ batch }) => {
          if (active) setBatch(batch);
        })
        .catch((e) => {
          if (active) setError(e.message);
        });
    return () => {
      active = false;
    };
  }, [draft.photoBatchId]);
  const candidates = state.dishes
    .filter((dish: Row) => !dish.archived_at)
    .map((dish: Row) => ({
      ...dish,
      source: state.assets.find(
        (a: Row) =>
          a.dish_id === dish.id && a.kind === "source" && !a.deleted_at,
      ),
    }));
  async function act(work: () => Promise<void>) {
    if (lock.current) return;
    lock.current = true;
    setBusy(true);
    setError("");
    try {
      await work();
      await refresh();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      lock.current = false;
      setBusy(false);
    }
  }
  async function begin() {
    const items = selected.map((id) => {
      const dish = candidates.find((d: Row) => d.id === id);
      return { dishId: id, sourceId: dish.source.id };
    });
    await remember(batchId.current);
    const result = await api("photo-batches", {
      batchId: batchId.current,
      items,
      style: styleFor(draft, state.restaurant),
      recipe: recipeFromDraft(draft, state.restaurant),
    });
    setBatch(result.batch);
    void api("jobs/tick", {}).catch(() => {});
  }
  const itemState = (item: Row, index: number) => {
    const submitted =
      index === 0
        ? null
        : state.batchItems.find((entry: Row) => entry.id === item.itemId);
    const jobId = index === 0 ? batch?.sampleJobId : submitted?.job_id;
    const output = state.outputs.find(
      (entry: Row) => entry.job_id === jobId && entry.status === "completed",
    );
    const job = state.jobs.find((entry: Row) => entry.id === jobId);
    const asset = state.assets.find(
      (entry: Row) => entry.id === output?.asset_id,
    );
    return {
      jobId,
      output,
      asset,
      failed: job?.status === "failed" || submitted?.status === "failed",
      error:
        submitted?.error ||
        state.outputs.find(
          (entry: Row) => entry.job_id === jobId && entry.status === "failed",
        )?.error,
    };
  };
  const sample = batch && itemState(batch.items[0], 0),
    remaining = batch ? batch.items.length - 1 : 0;
  const eligibleExports = batch
    ? batch.items
        .map(itemState)
        .filter(
          (entry: Row) =>
            entry.asset?.approved_at &&
            !entry.asset.needs_correction &&
            included.includes(entry.asset.id),
        )
    : [];
  async function exportSet() {
    const attemptId = crypto.randomUUID();
    const { zipSync } = await import("fflate");
    const files: Record<string, Uint8Array> = {};
    for (const entry of eligibleExports) {
      const dish = state.dishes.find((d: Row) => d.id === entry.asset.dish_id);
      const photo = await masterPhotoExport(entry.asset.id);
      track(
        "export_prepared",
        entry.asset.id,
        { destination: "master" },
        `${entry.asset.id}:master`,
      );
      files[
        photoFilename(
          {
            assetId: entry.asset.id,
            dishId: dish.id,
            name: dish.name,
            fromPhoto: true,
          },
          "master",
          photo.extension,
        )
      ] = new Uint8Array(await photo.blob.arrayBuffer());
    }
    const bytes = zipSync(files, { level: 0 });
    downloadBlob(
      new Blob([new Uint8Array(bytes)], { type: "application/zip" }),
      "restaurant-photos.zip",
    );
    setNotice("Download started. Each file keeps its full saved quality.");
    for (const entry of eligibleExports)
      track(
        "export_download_started",
        entry.asset.id,
        {
          destination: "photo-set",
          count: eligibleExports.length,
        },
        attemptId,
      );
  }
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open && !busy) onClose();
      }}
    >
      <DialogContent
        onCloseAutoFocus={onCloseAutoFocus}
        className="cx-workspace-popover ps2-dialog ps2-batch"
        showCloseButton={false}
        onEscapeKeyDown={(e) => {
          if (busy) e.preventDefault();
        }}
      >
        <header className="ps2-dialog-header">
          <div>
            <DialogTitle>One look. More dishes.</DialogTitle>
            <DialogDescription>
              Create one sample first. Review it before continuing with the
              rest.
            </DialogDescription>
          </div>
          <button
            className="ps2-icon-button"
            aria-label="Close photo set"
            disabled={busy}
            onClick={onClose}
          >
            <X size={21} />
          </button>
        </header>
        <div className="ps2-dialog-scroll">
          {error && (
            <p className="cx-feedback error" role="alert">
              {error}
            </p>
          )}
          {notice && <p role="status">{notice}</p>}
          {!batch ? (
            <>
              <p>
                Choose up to 8 dishes with an original photo. The first selected
                dish becomes your sample.
              </p>
              <div className="ps2-batch-grid">
                {candidates.map((dish: Row) => {
                  const checked = selected.includes(dish.id),
                    eligible = !!dish.source && !!dish.confirmed_at;
                  return (
                    <label key={dish.id} className="ps2-batch-choice">
                      <input
                        type="checkbox"
                        checked={checked}
                        disabled={
                          busy ||
                          !eligible ||
                          (!checked && selected.length >= 8)
                        }
                        onChange={() =>
                          setSelected((ids) =>
                            checked
                              ? ids.filter((id) => id !== dish.id)
                              : [...ids, dish.id],
                          )
                        }
                      />
                      {dish.source && (
                        <img
                          src={`/api/assets/${dish.source.id}`}
                          alt="Original dish photo"
                          loading="lazy"
                        />
                      )}
                      <span>
                        <b>{dish.name}</b>
                        <small>
                          {!dish.source
                            ? "Add an original photo in My Dishes"
                            : !dish.confirmed_at
                              ? "Confirm dish details first"
                              : selected[0] === dish.id
                                ? "First sample"
                                : "Original photo ready"}
                        </small>
                      </span>
                    </label>
                  );
                })}
              </div>
              {!candidates.length && (
                <p>
                  Add dish photos in My Dishes, then come back to build a set.
                </p>
              )}
              <p>
                {selected.length} selected · {selected.length} images total if
                you continue. Only the first image is used now.
              </p>
              <button
                className="cx-btn"
                disabled={
                  busy ||
                  !selected.length ||
                  state.remaining < 1 ||
                  !state.aiConnected
                }
                onClick={() => void act(begin)}
              >
                Create sample · 1 image
              </button>
              {!state.aiConnected && (
                <p>
                  Image creation is unavailable. Your existing photos are safe.
                </p>
              )}
            </>
          ) : (
            <>
              <div className="ps2-batch-grid">
                {batch.items.map((item: Row, index: number) => {
                  const result = itemState(item, index),
                    dish = state.dishes.find(
                      (dish: Row) => dish.id === item.dishId,
                    );
                  return (
                    <article className="ps2-batch-result" key={item.itemId}>
                      <img
                        src={`/api/assets/${result.asset?.id || item.sourceId}`}
                        alt={
                          result.asset
                            ? `${dish?.name} result`
                            : `${dish?.name} original`
                        }
                        loading="lazy"
                      />
                      <b>{dish?.name || "Dish photo"}</b>
                      <p>
                        {result.asset?.needs_correction
                          ? "Needs correction"
                          : result.asset?.approved_at
                            ? "Approved"
                            : result.asset
                              ? "Needs your review"
                              : result.failed
                                ? "Couldn’t create this photo"
                                : index > 0 && !batch.continued
                                  ? "Waiting for sample approval"
                                  : "Creating…"}
                      </p>
                      {result.error && <p role="alert">{result.error}</p>}
                      {result.asset && (
                        <button
                          className="cx-link"
                          disabled={busy}
                          onClick={() =>
                            onReview(item, result.jobId, result.asset.id)
                          }
                        >
                          Review photo
                        </button>
                      )}
                      {result.asset?.approved_at &&
                        !result.asset.needs_correction && (
                          <label>
                            <input
                              type="checkbox"
                              checked={included.includes(result.asset.id)}
                              onChange={(e) =>
                                setIncluded((ids) =>
                                  e.target.checked
                                    ? [...ids, result.asset.id]
                                    : ids.filter(
                                        (id) => id !== result.asset.id,
                                      ),
                                )
                              }
                            />
                            Include in download
                          </label>
                        )}
                      {result.failed && (
                        <button
                          className="cx-link"
                          disabled={
                            busy || !state.aiConnected || state.remaining < 1
                          }
                          onClick={() =>
                            void act(async () => {
                              await api(
                                index === 0
                                  ? `photo-batches/${batchId.current}/retry-sample`
                                  : "batches/retry",
                                index === 0 ? {} : { id: item.itemId },
                              );
                              void api("jobs/tick", {}).catch(() => {});
                            })
                          }
                        >
                          Retry this photo · 1 image
                        </button>
                      )}
                    </article>
                  );
                })}
              </div>
              {!batch.continued && remaining > 0 && (
                <>
                  <p>
                    {sample?.asset?.approved_at &&
                    !sample.asset.needs_correction
                      ? `Continue with the remaining ${remaining} dishes. Uses ${remaining} images · ${state.remaining} remaining.`
                      : "Review and approve your sample to continue. The remaining images have not been charged."}
                  </p>
                  <button
                    className="cx-btn"
                    disabled={
                      busy ||
                      !state.aiConnected ||
                      !sample?.asset?.approved_at ||
                      !!sample?.asset?.needs_correction ||
                      state.remaining < remaining
                    }
                    onClick={() =>
                      void act(async () => {
                        await api(`photo-batches/${batchId.current}/continue`, {
                          remainingCount: remaining,
                        });
                        setBatch({ ...batch, continued: true });
                        void api("jobs/tick", {}).catch(() => {});
                      })
                    }
                  >
                    Create remaining {remaining} · {remaining} images
                  </button>
                </>
              )}
              <p className="ps2-control-help">
                Review every result separately. Download includes only the
                approved photos you select, at full saved quality with no new
                crop.
              </p>
              <button
                className="cx-btn cx-secondary"
                disabled={busy || !eligibleExports.length}
                onClick={() => void act(exportSet)}
              >
                Download selected ({eligibleExports.length})
              </button>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

