    const stillOpen = quickActive.current === session.id;
    if (stillOpen) {
      change({
        resultId: data.id,
        format: values.format,
        ...(session.assetId === b.sourceId ? { jobId: "" } : {}),
        adjustments: { ...emptyAdjustments },
        step: 4,
