  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { api, normalizePhoto, type Row } from "@/lib/client";
import RestaurantStyle from "./restaurant-style";

type Group = "details" | "look" | "ordering";
type Props = {
  open: boolean;
  close: () => void;
  state: Row;
  act: (label: string, action: () => Promise<void>) => unknown;
  refresh: () => Promise<void>;
  busy: unknown;
};
function restaurantProfile(restaurant: Row): Row {
  return {
    name: restaurant.name || "",
    cuisine: restaurant.cuisine || "",
    brand: restaurant.brand || "",
    currency: restaurant.currency || "USD",
    style: restaurant.style,
    timezone: restaurant.timezone || "America/New_York",
    orderingUrl: restaurant.ordering_url || "",
    hours: restaurant.hours,
  };
}
export default function RestaurantSettings({
  open,
  close,
  state,
  act,
  refresh,
  busy,
}: Props) {
  const [profile, setProfile] = useState<Row>(() =>
    restaurantProfile(state.restaurant),
  );
  const [baseline, setBaseline] = useState(() => JSON.stringify(profile));
  const [group, setGroup] = useState<Group>("details");
  const [discard, setDiscard] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);
  const previouslyOpen = useRef(false);
  const saveLock = useRef(false);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const formId = useId();
  const dirty = JSON.stringify(profile) !== baseline;
  const working = saving || !!busy;
  useEffect(() => {
    if (open && !previouslyOpen.current) {
      const next = restaurantProfile(state.restaurant);
      setProfile(next);
      setBaseline(JSON.stringify(next));
      setGroup("details");
      setError("");
      setSaved(false);
      setDiscard(false);
    }
    previouslyOpen.current = open;
  }, [open, state.restaurant]);
  useEffect(() => {
    if (!open || !dirty) return;
    const warn = (event: BeforeUnloadEvent) => {
      event.preventDefault();
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [open, dirty]);
  function requestClose() {
    if (working) return;
    if (dirty) setDiscard(true);
    else close();
  }
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saveLock.current || working) return;
    const invalid = Array.from(event.currentTarget.elements).find(
      (element) =>
        element instanceof HTMLInputElement && !element.validity.valid,
    ) as HTMLInputElement | undefined;
    if (invalid) {
      const nextGroup = invalid.closest<HTMLElement>("[data-settings-group]")
        ?.dataset.settingsGroup;
      if (nextGroup) setGroup(nextGroup as Group);
      setError(invalid.validationMessage);
      requestAnimationFrame(() => invalid.focus());
      return;
    }
    if (!String(profile.name).trim()) {
      setGroup("details");
      setError("Enter your restaurant name.");
      requestAnimationFrame(() =>
        document.getElementById(formId + "-name")?.focus(),
      );
      return;
    }
    try {
      new Intl.DateTimeFormat("en", { timeZone: profile.timezone }).format();
    } catch {
      setGroup("ordering");
      setError("Choose a valid restaurant timezone, such as America/New_York.");
      const timezoneInput = event.currentTarget.elements.namedItem("timezone");
      if (timezoneInput instanceof HTMLElement) {
        requestAnimationFrame(() => timezoneInput.focus());
      }
      return;
    }
    saveLock.current = true;
    setSaving(true);
    setError("");
    try {
      await api("restaurant", profile);
      setBaseline(JSON.stringify(profile));
      setSaved(true);
      await refresh();
    } catch (reason) {
      setError((reason as Error).message);
    } finally {
      saveLock.current = false;
      setSaving(false);
    }
  }
  return (
    <>
      <Dialog
        open={open}
        onOpenChange={(value) => {
          if (!value) requestClose();
        }}
      >
        <DialogContent
          className="cx-workspace-popover restaurant-dialog rs-dialog"
          showCloseButton={false}
        >
          <header className="rs-header">
            <div>
              <DialogTitle>Your restaurant</DialogTitle>
              <DialogDescription>
                The details behind everything you make.
              </DialogDescription>
            </div>
            <button
              className="cx-icon"
              aria-label="Close restaurant settings"
              disabled={working}
              onClick={requestClose}
            >
              <X size={20} />
            </button>
          </header>
          <Tabs
            value={group}
            onValueChange={(value) => setGroup(value as Group)}
            className="rs-tabs"
          >
            <TabsList
              variant="line"
              className="rs-tab-list"
              aria-label="Restaurant settings"
            >
              <TabsTrigger value="details">Details</TabsTrigger>
              <TabsTrigger value="look">Restaurant look</TabsTrigger>
              <TabsTrigger value="ordering">Ordering & hours</TabsTrigger>
            </TabsList>
            <form id={formId} className="rs-body" noValidate onSubmit={save}>
              <fieldset className="rs-fields" disabled={working}>
                <TabsContent
                  forceMount
                  hidden={group !== "details"}
                  value="details"
                  data-settings-group="details"
                  className="rs-panel"
                >
                  {["name", "cuisine", "brand"].map((key) => (
                    <label className="field" key={key}>
                      {key === "name"
                        ? "Restaurant name"
                        : key === "cuisine"
                          ? "Cuisine"
                          : "Brand preferences"}
                      <input
                        id={key === "name" ? formId + "-name" : undefined}
                        required={key === "name"}
                        value={profile[key]}
                        disabled={working}
                        onChange={(event) =>
                          setProfile({ ...profile, [key]: event.target.value })
                        }
                      />
                    </label>
                  ))}
                  <label className="field">
                    Menu currency
                    <select
                      value={profile.currency}
                      disabled={working}
                      onChange={(event) =>
                        setProfile({ ...profile, currency: event.target.value })
                      }
                    >
                      {["USD", "GBP", "EUR", "JPY", "CAD", "AUD"].map(
                        (currency) => (
                          <option key={currency}>{currency}</option>
                        ),
                      )}
                    </select>
                  </label>
                  <label className="field">
                    Logo (optional)
                    {state.restaurant.logo_id && (
                      <img
                        className="rs-logo"
                        src={`/api/assets/${state.restaurant.logo_id}`}
                        alt="Current restaurant logo"
                      />
                    )}
                    <input
                      type="file"
                      accept="image/jpeg,image/png,image/heic,.heic"
                      disabled={working}
                      onChange={(event) => {
                        const file = event.target.files?.[0];
                        if (file)
                          act("Saving logo", async () => {
                            const form = new FormData();
                            form.set("file", file);
                            form.set(
                              "normalized",
                              await normalizePhoto(file),
                              "logo.jpg",
                            );
                            form.set("kind", "logo");
                            await api("assets", form);
                            await refresh();
                          });
                      }}
                    />
                    <small>Logo uploads save immediately.</small>
                  </label>
                </TabsContent>
                <TabsContent
                  forceMount
                  hidden={group !== "look"}
                  value="look"
                  data-settings-group="look"
                  className="rs-panel"
                >
                  <RestaurantStyle
                    {...{ profile, setProfile, state, act, refresh }}
                    busy={working}
                    section="look"
                  />
                </TabsContent>
                <TabsContent
                  forceMount
                  hidden={group !== "ordering"}
                  value="ordering"
                  data-settings-group="ordering"
                  className="rs-panel"
                >
                  <RestaurantStyle
                    {...{ profile, setProfile, state, act, refresh }}
                    busy={working}
                    section="ordering"
                  />
                </TabsContent>
              </fieldset>
            </form>
          </Tabs>
          <footer className="rs-footer">
            {error && (
              <p className="rs-error" role="alert">
                {error}
              </p>
            )}
            <div className="rs-save-row">
              <span role="status">
                {saving ? (
                  "Saving…"
                ) : dirty ? (
                  "Unsaved changes"
                ) : saved ? (
                  <>
                    <Check size={16} /> Changes saved
                  </>
                ) : (
                  "Your details are up to date"
                )}
              </span>
              <button
                ref={closeButtonRef}
                className="cx-btn"
                type="submit"
                form={formId}
                disabled={working || !dirty}
              >
                {saving ? "Saving…" : "Save changes"}
              </button>
            </div>
            <p>Publish your menu to make its changes live.</p>
          </footer>
        </DialogContent>
      </Dialog>
      <AlertDialog open={discard} onOpenChange={setDiscard}>
        <AlertDialogContent
          className="cx-workspace-popover"
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            closeButtonRef.current?.focus();
          }}
        >
          <AlertDialogHeader>
            <AlertDialogTitle>Discard your changes?</AlertDialogTitle>
            <AlertDialogDescription>
              Your unsaved restaurant details will be lost. You can keep editing
              and save them first.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep editing</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => {
                setDiscard(false);
                close();
              }}
            >
              Discard changes
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { api, normalizePhoto, type Row } from "@/lib/client";
import { defaultStyle } from "@/lib/promotions";
import RestaurantLookEditor from "./restaurant-look-editor";
export default function RestaurantStyle({
  profile,
  setProfile,
  state,
  act,
  refresh,
  busy,
  section = "all",
}: Row) {
  const [uploaded, setUploaded] = useState("");
  const style = { ...defaultStyle, ...profile.style };
  const change = (k: string, v: unknown) =>
    setProfile({ ...profile, style: { ...style, [k]: v } });
  const hours =
    profile.hours?.length === 7
      ? profile.hours
      : Array.from({ length: 7 }, (_, day) => ({
          day,
          open: "11:00",
          close: "21:00",
          closed: false,
        }));
  return (
    <>
      {section !== "ordering" && (
        <>
          <RestaurantLookEditor {...{ profile, setProfile, style, state }} />
          <label className="field">
            Caption tone
            <input
              value={style.tone}
              maxLength={150}
              onChange={(e) => change("tone", e.target.value)}
            />
          </label>
          <label className="field">
            Your tables, backgrounds or menu photos{" "}
            <small>Choose up to 3 atmosphere references.</small>
            <input
              type="file"
              accept="image/jpeg,image/png,image/heic,.heic"
              disabled={!!busy}
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (f)
                  act("Saving style reference", async () => {
                    const form = new FormData();
                    form.set("file", f);
                    form.set(
                      "normalized",
                      await normalizePhoto(f),
                      "reference.jpg",
                    );
                    form.set("kind", "reference");
                    const a = await api("assets", form);
                    change(
                      "referenceIds",
                      [...style.referenceIds, a.id].slice(-3),
                    );
                    setUploaded(
                      "Reference uploaded. Save your restaurant to apply it.",
                    );
                    await refresh();
                  });
              }}
            />
          </label>
          {uploaded && (
            <p role="status" className="fine">
              {uploaded}
            </p>
          )}
          <div className="reference-grid">
            {state.assets
              .filter((a: Row) => a.kind === "reference")
              .map((a: Row) => (
                <label key={a.id}>
                  <img src={"/api/assets/" + a.id} alt={a.name} />
                  <span>
                    <input
                      type="checkbox"
                      checked={style.referenceIds.includes(a.id)}
                      onChange={(e) =>
                        change(
                          "referenceIds",
                          e.target.checked
                            ? [...style.referenceIds, a.id].slice(-3)
                            : style.referenceIds.filter(
                                (v: string) => v !== a.id,
                              ),
                        )
                      }
                    />{" "}
                    Use reference
                  </span>
                </label>
              ))}
          </div>
        </>
      )}
      {section !== "look" && (
        <>
          <label className="field">
            Restaurant timezone
            <input
              name="timezone"
              list="restaurant-timezones"
              value={profile.timezone || "America/New_York"}
              onChange={(e) =>
                setProfile({ ...profile, timezone: e.target.value })
              }
            />
            <datalist id="restaurant-timezones">
              {[
                "America/New_York",
                "America/Chicago",
                "America/Denver",
                "America/Los_Angeles",
                "Europe/London",
                "Europe/Paris",
                "Asia/Tokyo",
                "Australia/Sydney",
                "UTC",
              ].map((v) => (
                <option key={v}>{v}</option>
              ))}
            </datalist>
            <small>Specials use this timezone, even when you travel.</small>
          </label>
          <label className="field">
            Existing ordering link
            <input
              type="url"
              placeholder="https://…"
              value={profile.orderingUrl || ""}
              onChange={(e) =>
                setProfile({ ...profile, orderingUrl: e.target.value })
              }
            />
          </label>
          <details className="dish-options">
            <summary>Opening hours</summary>
            <p className="fine">
              Set your actual hours for weekly suggestions. A closing time
              before opening means the following day.
            </p>
            {hours.map((h: Row, i: number) => (
              <div className="hours-row" key={h.day}>
                <b>
                  {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][h.day]}
                </b>
                <input
                  aria-label={
                    "Opens " +
                    [
                      "Sunday",
                      "Monday",
                      "Tuesday",
                      "Wednesday",
                      "Thursday",
                      "Friday",
                      "Saturday",
                    ][h.day]
                  }
                  type="time"
                  value={h.open}
                  disabled={h.closed}
                  onChange={(e) =>
                    setProfile({
                      ...profile,
                      hours: hours.map((x: Row, j: number) =>
                        j === i ? { ...x, open: e.target.value } : x,
                      ),
                    })
                  }
                />
                <input
                  aria-label={
                    "Closes " +
                    [
                      "Sunday",
                      "Monday",
                      "Tuesday",
                      "Wednesday",
                      "Thursday",
                      "Friday",
                      "Saturday",
                    ][h.day]
                  }
                  type="time"
                  value={h.close}
                  disabled={h.closed}
                  onChange={(e) =>
                    setProfile({
                      ...profile,
                      hours: hours.map((x: Row, j: number) =>
                        j === i ? { ...x, close: e.target.value } : x,
                      ),
                    })
                  }
                />
                <label>
                  <input
                    type="checkbox"
                    aria-label={
                      [
                        "Sunday",
                        "Monday",
                        "Tuesday",
                        "Wednesday",
                        "Thursday",
                        "Friday",
                        "Saturday",
                      ][h.day] + " closed"
                    }
                    checked={h.closed}
                    onChange={(e) =>
                      setProfile({
                        ...profile,
                        hours: hours.map((x: Row, j: number) =>
                          j === i ? { ...x, closed: e.target.checked } : x,
                        ),
                      })
                    }
                  />{" "}
                  Closed
                </label>
              </div>
            ))}
            {!profile.hours?.length && (
              <Button
                type="button"
                variant="outline"
                onClick={() => setProfile({ ...profile, hours })}
              >
                Use these hours
              </Button>
            )}
          </details>
        </>
      )}
    </>
  );
}

"use client";
import { useId, useState } from "react";
import { X } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { recipeFromDraft } from "@/lib/studio-library";
import type { Row } from "@/lib/client";
import { useStudioLibrary } from "./use-studio-library";
export function SavePhotoLookSheet({
  state,
  draft,
  assetId,
  onClose,
  onCloseAutoFocus,
}: {
  state: Row;
  draft: Row;
  assetId: string;
  onClose: () => void;
  onCloseAutoFocus: (event: Event) => void;
}) {
  const formId = useId();
  const store = useStudioLibrary(state.restaurant.id),
    [name, setName] = useState(draft.savedLookName || "Our restaurant look"),
    [savedId, setSavedId] = useState("");
  async function save() {
    const recipe = recipeFromDraft(draft, state.restaurant),
      id = crypto.randomUUID();
    if (
      await store.mutate((library) => ({
        ...library,
        looks: [
          ...library.looks,
          {
            id,
            name: name.trim(),
            recipe,
            previewAssetId: assetId,
            archived: false,
            version: 1,
            compatibleSubjects:
              recipe.plate === "keep" ? ["food", "drinks"] : ["food"],
          },
        ],
      }))
    )
      setSavedId(id);
  }
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open && !store.busy) onClose();
      }}
    >
      <DialogContent
        onCloseAutoFocus={onCloseAutoFocus}
        className="cx-workspace-popover ps2-dialog ps2-save-dialog"
        showCloseButton={false}
      >
        <header className="ps2-dialog-header">
          <div>
            <DialogTitle>
              {savedId ? "Your look is saved." : "Keep this look."}
            </DialogTitle>
            <DialogDescription>
              Reuse the setting and light with another dish. Your approved photo
              becomes the example.
            </DialogDescription>
          </div>
          <button
            className="ps2-icon-button"
            disabled={store.busy}
            aria-label="Close saved look"
            onClick={onClose}
          >
            <X size={20} />
          </button>
        </header>
        <div className="ps2-save-form ps2-dialog-scroll">
          <img
            className="ps2-saved-preview"
            src={`/api/assets/${assetId}`}
            alt="Approved example for this saved look"
          />
          {store.error && (
            <p role="alert">
              {store.error}
              <button className="cx-link" onClick={() => void store.reload()}>
                Reload saved looks
              </button>
            </p>
          )}
          {savedId ? (
            <>
              <p>Available in Browse all looks → Saved.</p>
              <button
                className="cx-btn cx-secondary"
                disabled={store.busy || store.library.defaultLookId === savedId}
                onClick={() =>
                  void store.mutate((value) => ({
                    ...value,
                    defaultLookId: savedId,
                  }))
                }
              >
                {store.library.defaultLookId === savedId
                  ? "Default for new photos"
                  : "Make my default for new photos"}
              </button>
              <p className="ps2-control-help">
                Applies to new Photo Studio drafts only. Existing photos, menus
                and posts keep their settings.
              </p>
            </>
          ) : (
            <form
              id={formId}
              onSubmit={(e) => {
                e.preventDefault();
                void save();
              }}
            >
              <label className="field">
                Look name
                <input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  maxLength={60}
                  autoFocus
                />
              </label>
              <p className="ps2-control-help">
                Saving a look keeps it in your collection. It does not change
                your default.
              </p>
              {store.library.looks.length >= 100 && (
                <p role="status">
                  Your collection has reached its 100-look limit.
                </p>
              )}
            </form>
          )}
        </div>
        <footer className="ps2-dialog-footer">
          <span>Only your restaurant can use this look</span>
          {savedId ? (
            <button className="cx-btn" disabled={store.busy} onClick={onClose}>
              Done
            </button>
          ) : (
            <button
              className="cx-btn"
              type="submit"
              form={formId}
              disabled={
                !store.ready ||
                store.busy ||
                !name.trim() ||
                store.library.looks.length >= 100
              }
            >
              {store.busy ? "Saving…" : "Save look"}
            </button>
          )}
        </footer>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { ArrowRight, ChevronLeft } from "lucide-react";
import { photoStyles } from "@/lib/studio";
import { orderedOccasions, studioOccasions } from "@/lib/studio-occasions";
import type { PhotoStyle } from "@/lib/photo-styles";
import { findOccasions } from "@/lib/studio-search";
export function StudioOccasions({
  timezone,
  query,
  active,
  onActive,
  explore,
  disabledStyleIds = [],
  onSearchAll,
  onResultCount,
}: {
  timezone?: string;
  query: string;
  active: string;
  onActive: (id: string) => void;
  explore: (
    look: PhotoStyle,
    occasion: string,
    trigger?: HTMLButtonElement,
  ) => void;
  disabledStyleIds?: string[];
  onSearchAll: () => void;
  onResultCount: (count: number) => void;
}) {
  const [collections] = useState(() => orderedOccasions(timezone));
  const section = useRef<HTMLElement>(null),
    heading = useRef<HTMLHeadingElement>(null),
    previousActive = useRef(active),
    previousQuery = useRef(query);
  useLayoutEffect(() => {
    const before = previousActive.current;
    const queryChanged = previousQuery.current !== query;
    previousActive.current = active;
    previousQuery.current = query;
    if (before === active || queryChanged) return;
    if (active) heading.current?.focus();
    else
      [
        ...(section.current?.querySelectorAll<HTMLButtonElement>(
          "[data-occasion-trigger]",
        ) || []),
      ]
        .find((button) => button.dataset.occasionTrigger === before)
        ?.focus();
  }, [active, query]);
  const current = studioOccasions.find((o) => o.id === active);
  const matching = findOccasions(query, collections, disabledStyleIds);
  const resultCount = matching.length;
  useEffect(() => onResultCount(resultCount), [resultCount, onResultCount]);
  return (
    <section ref={section} className="ps2-occasions">
      {current ? (
        <>
          <div className="ps2-occasion-heading">
            <h3 ref={heading} tabIndex={-1}>
              {current.name}
            </h3>
            <button className="cx-link" onClick={() => onActive("")}>
              <ChevronLeft size={16} />
              All occasions
            </button>
          </div>
          <p>{current.description}</p>
          <div className="ps2-gallery">
            {current.looks
              .filter((id) => !disabledStyleIds.includes(id))
              .map((id) => {
                const look = photoStyles.find((style) => style.id === id)!;
                return (
                  <button
                    key={id}
                    className="ps2-occasion-card"
                    data-look-detail={`occasion-look:${id}`}
                    onClick={(event) =>
                      explore(look, current.id, event.currentTarget)
                    }
                  >
                    <img
                      src={look.image}
                      alt={`${look.name} style example`}
                      loading="lazy"
                      width={512}
                      height={512}
                    />
                    <span>
                      <b>{look.name}</b>
                      <small>{look.cue}</small>
                      <ArrowRight size={18} />
                    </span>
                  </button>
                );
              })}
          </div>
          {current.looks.every((id) => disabledStyleIds.includes(id)) && (
            <p role="status">
              These looks are temporarily unavailable. Choose another occasion.
            </p>
          )}
          <p className="ps2-control-help">
            Scene inspiration only. Your food, portion and serving dish stay
            yours. Add promotional wording later in Post Maker.
          </p>
        </>
      ) : (
        <>
          <p>
            Find a setting for the moment. Explore the curated looks in each
            collection.
          </p>
          <div className="ps2-occasion-grid">
            {matching.map((occasion) => (
              <button
                key={occasion.id}
                className="ps2-occasion-card"
                data-occasion-trigger={occasion.id}
                onClick={() => onActive(occasion.id)}
              >
                <img
                  src={
                    photoStyles.find(
                      (look) =>
                        look.id ===
                        occasion.looks.find(
                          (id) => !disabledStyleIds.includes(id),
                        ),
                    )!.image
                  }
                  alt={`${occasion.name} style inspiration`}
                  loading="lazy"
                  width={512}
                  height={512}
                />
                <span>
                  <b>{occasion.name}</b>
                  <small>{occasion.description}</small>
                  <ArrowRight size={18} />
                </span>
              </button>
            ))}
          </div>
          {!matching.length && (
            <div className="ps2-empty-results">
              <h3 role="status">No matching occasion.</h3>
              <p>
                Try Christmas, game day, Valentine’s or summer, or search the
                full collection.
              </p>
              <button className="cx-btn" onClick={onSearchAll}>
                Search all looks
                <ArrowRight size={16} />
              </button>
            </div>
          )}
        </>
      )}
    </section>
  );
}

