  create,
  quickEdit,
  openMenu,
  refreshAvailability,
}: {
  draft: Row;
  state: Row;
  selected: PhotoStyle;
  styleImage: string;
  source: string;
  busy: string;
  advice: string;
  update: (patch: Row) => void;
  chooseLook: (id: string) => void;
  matchRestaurant: (enabled: boolean) => void;
  uploadPhoto: (file: File) => void;
  referencePhoto: InspirationPhoto | null;
  applyInspiration: (
