"use client";
import {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import Auth from "./components/auth";
import Landing from "./components/plateworthy-landing";
import Brand from "./components/brand";
import WorkspacePlaceholder from "./components/workspace-placeholder";
import { api, type Row } from "@/lib/client";
const GuestStudio = lazy(() => import("./components/guest-studio"));
const PlanDialog = lazy(() => import("./components/plan-dialog"));
const CoreWorkspace = lazy(() => import("./components/core-workspace"));
const SettingsPanel = lazy(() =>
  import("./components/account-panels").then((m) => ({
    default: m.SettingsPanel,
  })),
);
const Admin = lazy(() =>
  import("./components/account-panels").then((m) => ({ default: m.Admin })),
);
export default function Home() {
  const [state, setState] = useState<Row>({
    user: null,
    dishes: [],
    assets: [],
    jobs: [],
    outputs: [],
    captions: [],
  });
  const [loaded, setLoaded] = useState(false),
    [auth, setAuth] = useState(false),
    [authMode, setAuthMode] = useState<"login" | "signup">("login"),
    [settings, setSettings] = useState(false),
    [guest, setGuest] = useState(false),
    [plans, setPlans] = useState(false),
    [busy, setBusy] = useState(""),
    [error, setError] = useState("");
  const actionBusy = useRef(false),
    tickBusy = useRef(false);
  const refresh = useCallback(async () => {
    const data = await api("state");
    setState(data);
    setLoaded(true);
  }, []);
  useEffect(() => {
    refresh().catch((e) => {
      setError(e.message);
      setLoaded(true);
    });
  }, [refresh]);
  useEffect(() => {
    if (state.user?.id) void api("events", { kind: "visit" }).catch(() => {});
  }, [state.user?.id]);
  useEffect(() => {
    let cancelled = false;
    if (loaded && !state.user && location.hash === "#studio") setGuest(true);
    if (loaded && state.user && location.hash === "#studio") {
      void import("@/lib/guest-studio-storage")
        .then(({ loadGuestDrafts }) => loadGuestDrafts())
        .then((drafts) => {
          if (
            !cancelled &&
            drafts.some(
              (draft) =>
                draft.requested &&
                (!draft.transfer?.restaurantId ||
                  draft.transfer.restaurantId === state.restaurant?.id),
            )
          )
            setGuest(true);
        })
        .catch(() => {});
    }
    if (loaded && new URLSearchParams(location.search).has("upgrade")) {
      if (state.user) setPlans(true);
      else {
        setAuthMode("signup");
        setAuth(true);
      }
    }
    return () => {
      cancelled = true;
    };
  }, [loaded, state.user?.id, state.restaurant?.id]);
  useEffect(() => {
    const open = () => setPlans(true);
    window.addEventListener("plateworthy:plans", open);
    return () => window.removeEventListener("plateworthy:plans", open);
  }, []);
  useEffect(() => {
    if (state.user && new URLSearchParams(location.search).has("billing"))
      setPlans(true);
  }, [state.user?.id]);
  useEffect(() => {
    if (!state.user) return;
    const timer = setInterval(async () => {
      if (tickBusy.current || document.hidden) return;
      tickBusy.current = true;
      try {
        if (
          state.batchItems?.some((b: Row) => b.status === "queued") ||
          state.jobs.some((j: Row) =>
            ["queued", "processing"].includes(j.status),
          )
        ) {
          await api("jobs/tick", {});
          await refresh();
        }
      } catch {
      } finally {
        tickBusy.current = false;
      }
    }, 2000);
    return () => clearInterval(timer);
  }, [state.user, state.jobs, state.batchItems, refresh]);
  async function act(label: string, fn: () => Promise<void>) {
    if (actionBusy.current) return;
    actionBusy.current = true;
    setBusy(label);
    setError("");
    try {
      await fn();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy("");
      actionBusy.current = false;
    }
  }
  if (!loaded)
    return (
      <main className="initial-loading">
        <Brand />
        <WorkspacePlaceholder
          title="Menu Material"
          message="Getting things ready…"
        />
      </main>
    );
  return (
    <>
      {guest ? (
        <Suspense
          fallback={
            <main className="initial-loading">
              <Brand />
              <WorkspacePlaceholder
                title="Photo Studio"
                message="Opening Photo Studio…"
              />
            </main>
          }
        >
          <GuestStudio
            state={state}
            onBack={() => {
              setGuest(false);
              history.replaceState(null, "", "/");
            }}
            onSignIn={() => {
              setAuthMode("login");
              setAuth(true);
            }}
            onSignup={() => {
              setAuthMode("signup");
              setAuth(true);
            }}
            onFinish={async () => {
              await refresh();
              setGuest(false);
            }}
          />
        </Suspense>
      ) : !state.user ? (
        <Landing
          signedIn={!!state.user}
          onStart={() => {
            setGuest(true);
            history.pushState(null, "", "/#studio");
          }}
          onSignIn={() => {
            setAuthMode("login");
            setAuth(true);
          }}
        />
      ) : (
        <Suspense
          fallback={
            <main className="initial-loading">
              <Brand />
              <WorkspacePlaceholder
                title="Your workspace"
                message="Opening your workspace…"
              />
            </main>
          }
        >
          <CoreWorkspace
            foreground={!settings && !plans && !auth}
            state={state}
            refresh={refresh}
            key={`${state.user.id}:${state.restaurant.id}`}
            onSettings={() => setSettings(true)}
            onPlans={() => setPlans(true)}
            onLogout={() =>
              act("Signing out", async () => {
                await api("auth/logout", {});
                const { clearExportImages } =
                  await import("@/lib/offer-export");
                clearExportImages();
                history.replaceState(
                  null,
                  "",
                  location.pathname + location.search,
                );
                await refresh();
              })
            }
            adminContent={
              state.user.role === "admin" ? (
                <Suspense
                  fallback={
                    <WorkspacePlaceholder
                      title="Administration"
                      layout="operations"
                      message="Opening administration…"
                    />
                  }
                >
                  <Admin act={act} refresh={refresh} busy={busy} />
                </Suspense>
              ) : null
            }
          />
        </Suspense>
      )}
      {error && (
        <div className="landing-error error" role="alert">
          {error}
          <button onClick={() => setError("")} aria-label="Dismiss error">
            ×
          </button>
        </div>
      )}
      <Auth
        open={auth}
        setOpen={setAuth}
        local={!!state.local}
        ownerSetup={!!state.ownerSetup}
        initialMode={authMode}
        billingEnabled={!!state.billing?.enabled}
        onDone={async () => {
          if (new URLSearchParams(location.search).has("upgrade"))
            setPlans(true);
          await refresh();
        }}
      />
      {plans && state.user && (
        <Suspense fallback={<p role="status">Opening your plan…</p>}>
          <PlanDialog
            open={plans}
            close={() => setPlans(false)}
            state={state}
            refresh={refresh}
          />
        </Suspense>
      )}
      {settings && (
        <Suspense fallback={<p role="status">Opening settings…</p>}>
          <SettingsPanel
            open={settings}
            close={() => setSettings(false)}
            state={state}
            act={act}
            refresh={refresh}
            busy={busy}
          />
        </Suspense>
      )}
    </>
  );
}

export type Row = Record<string, any>;
export async function api(
  path: string,
  body?: unknown,
  method?: string,
  signal?: AbortSignal,
) {
  const res = await fetch("/api/" + path, {
    signal,
    keepalive: path === "creation-events",
    method: method || (body === undefined ? "GET" : "POST"),
    headers:
      body instanceof FormData
        ? {}
        : body === undefined
          ? {}
          : { "Content-Type": "application/json" },
    body:
      body === undefined
        ? undefined
        : body instanceof FormData
          ? body
          : JSON.stringify(body),
  });
  const data = (await res.json().catch(() => null)) as Row | null;
  if (!res.ok)
    throw Object.assign(
      new Error(
        data?.error ||
          "The service couldn’t complete that action. Please try again.",
      ),
      {
        status: res.status,
      },
    );
  if (!data)
    throw Error(
      "The service returned an incomplete response. Please try again.",
    );
  return data;
}
export async function normalizePhoto(file: File): Promise<Blob> {
  if (!file.size)
    throw Error("This photo is empty. Please choose another photo.");
  if (file.size > 20 * 1024 * 1024)
    throw Error("Please choose a photo smaller than 20 MB.");
  let bitmap: ImageBitmap;
  try {
    // Let devices with native HEIC support keep orientation and avoid conversion.
    bitmap = await createImageBitmap(file, { imageOrientation: "from-image" });
  } catch {
    if (/\.hei[cf]$/i.test(file.name) || /hei[cf]/i.test(file.type)) {
      try {
        const { default: heic2any } = await import("heic2any");
        const result = await heic2any({
          blob: file,
          toType: "image/jpeg",
          quality: 0.9,
        });
        bitmap = await createImageBitmap(
          Array.isArray(result) ? result[0] : result,
          { imageOrientation: "from-image" },
        );
      } catch {
        throw Error(
          "This HEIC photo couldn’t be opened. Choose a JPEG version, or use Take a photo.",
        );
      }
    } else
      throw Error(
        "This photo couldn’t be opened. Choose a JPG, PNG or HEIC photo and try again.",
      );
  }
  if (bitmap.width * bitmap.height > 80_000_000) {
    bitmap.close();
    throw Error(
      "This photo is too large to process. Please export a smaller version.",
    );
  }
  const scale = Math.min(1, 2048 / Math.max(bitmap.width, bitmap.height));
  const c = document.createElement("canvas");
  c.width = Math.round(bitmap.width * scale);
  c.height = Math.round(bitmap.height * scale);
  const ctx = c.getContext("2d")!;
  ctx.fillStyle = "white";
  ctx.fillRect(0, 0, c.width, c.height);
  ctx.drawImage(bitmap, 0, 0, c.width, c.height);
  bitmap.close();
  return new Promise((resolve, reject) =>
    c.toBlob(
      (b) => (b ? resolve(b) : reject(Error("Photo could not be prepared."))),
      "image/jpeg",
      0.9,
    ),
  );
}
export async function exportImage(asset: Row, format: string, ratio: string) {
  const res = await fetch(`/api/assets/${asset.id}?download=1`);
  if (!res.ok) throw Error("Approve this image before downloading.");
  const bitmap = await createImageBitmap(await res.blob());
  const aspect = ratio === "portrait" ? 4 / 5 : ratio === "story" ? 9 / 16 : 1;
  const sw = Math.min(bitmap.width, bitmap.height * aspect),
    sh = sw / aspect;
  const c = document.createElement("canvas");
  c.width = 1080;
  c.height = Math.round(1080 / aspect);
  c.getContext("2d")!.drawImage(
    bitmap,
    (bitmap.width - sw) / 2,
    (bitmap.height - sh) / 2,
    sw,
    sh,
    0,
    0,
    c.width,
    c.height,
  );
  bitmap.close();
  const blob = await new Promise<Blob>((resolve, reject) =>
    c.toBlob(
      (b) => (b ? resolve(b) : reject(Error("Export failed."))),
      "image/" + format,
      0.94,
    ),
  );
  downloadBlob(
    blob,
    `plateworthy-${ratio}.${format === "jpeg" ? "jpg" : "png"}`,
  );
  await api("events", { kind: "image_downloaded", entityId: asset.id });
}
export function downloadBlob(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Mobile save sheets may continue reading after the click handler finishes.
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}
export function money(price: number, currency = "USD") {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency,
  }).format(price / 100);
}

// Local-only Vite alias. Never imported into a production Worker.
import { DatabaseSync } from "node:sqlite";
import {
  mkdirSync,
  readFileSync,
  writeFileSync,
  existsSync,
  readdirSync,
  unlinkSync,
  statSync,
} from "node:fs";
import { join, resolve, dirname } from "node:path";
const root = resolve(process.env.DISHLIGHT_DATA_DIR || ".local-data");
mkdirSync(root, { recursive: true });
const globalStore = globalThis as any;
const sqlite: DatabaseSync = (globalStore.__dishlightSqlite ??=
  new DatabaseSync(join(root, "dishlight.sqlite")));
sqlite.exec(
  "PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS _local_migrations (name TEXT PRIMARY KEY)",
);
if (existsSync("drizzle"))
  for (const file of readdirSync("drizzle")
    .filter((x) => x.endsWith(".sql"))
    .sort()) {
    if (
      !sqlite.prepare("SELECT 1 FROM _local_migrations WHERE name=?").get(file)
    ) {
      sqlite.exec("BEGIN");
      try {
        sqlite.exec(readFileSync(join("drizzle", file), "utf8"));
        sqlite
          .prepare("INSERT INTO _local_migrations (name) VALUES (?)")
          .run(file);
        sqlite.exec("COMMIT");
      } catch (e) {
        sqlite.exec("ROLLBACK");
        throw e;
      }
    }
  }
class Statement {
  constructor(
    private sql: string,
    private values: any[] = [],
  ) {}
  bind(...v: any[]) {
    return new Statement(this.sql, v);
  }
  async first(column?: string) {
    const r = sqlite.prepare(this.sql).get(...this.values) as any;
    return column ? (r?.[column] ?? null) : (r ?? null);
  }
  executeAll() {
    return {
      results: sqlite.prepare(this.sql).all(...this.values),
      success: true,
      meta: {},
    };
  }
  async all() {
    return this.executeAll();
  }
  async run() {
    const v = sqlite.prepare(this.sql).run(...this.values);
    return {
      success: true,
      meta: {
        changes: Number(v.changes),
        last_row_id: Number(v.lastInsertRowid),
      },
    };
  }
}
const DB = {
  prepare: (s: string) => new Statement(s),
  async batch(statements: Statement[]) {
    sqlite.exec("BEGIN IMMEDIATE");
    try {
      const results = [];
      for (const s of statements) results.push(s.executeAll());
      sqlite.exec("COMMIT");
      return results;
    } catch (e) {
      sqlite.exec("ROLLBACK");
      throw e;
    }
  },
};
const objectPath = (key: string) => {
  if (key.includes("..") || key.startsWith("/"))
    throw Error("Invalid object key");
  return join(root, "objects", key);
};
const BUCKET = {
  async put(key: string, value: any, options: any = {}) {
    const p = objectPath(key);
    mkdirSync(dirname(p), { recursive: true });
    const bytes =
      value instanceof ReadableStream
        ? await new Response(value).arrayBuffer()
        : value;
    writeFileSync(p, Buffer.from(bytes));
    writeFileSync(p + ".meta", JSON.stringify(options));
    return { key };
  },
  async head(key: string) {
    const p = objectPath(key);
    return existsSync(p) ? { key, size: statSync(p).size } : null;
  },
  async get(key: string) {
    const p = objectPath(key);
    if (!existsSync(p)) return null;
    const b = readFileSync(p);
    const meta = JSON.parse(readFileSync(p + ".meta", "utf8"));
    return {
      key,
      body: new Response(b).body,
      size: b.length,
      httpMetadata: meta.httpMetadata || {},
      arrayBuffer: async () =>
        b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength),
      writeHttpMetadata(h: Headers) {
        h.set(
          "Content-Type",
          meta.httpMetadata?.contentType || "application/octet-stream",
        );
      },
    };
  },
  async delete(key: string | string[]) {
    for (const k of Array.isArray(key) ? key : [key])
      for (const p of [objectPath(k), objectPath(k) + ".meta"])
        if (existsSync(p)) unlinkSync(p);
  },
};
export const env = { ...process.env, DB, BUCKET, LOCAL_DEVELOPMENT: "true" };

import { renderComposedPost } from "./post-composition";
import { drawPhoto, imageBitmap } from "./photo-export";
import { money, type Row } from "./client";
import { getPostTemplate } from "./post-templates";
import { emptyAdjustments } from "./studio";
import { loadPostFonts } from "./post-fonts";
import { brandTypeface } from "./restaurant-look";

export async function renderPost(
  canvas: HTMLCanvasElement,
  draft: Row,
  restaurant: Row,
  channel = "feed",
  slide = 0,
) {
  if (draft.compositionVersion === 2)
    return renderComposedPost(canvas, draft, restaurant, channel, slide);
  await loadPostFonts();
  const W = 1080,
    H = channel === "story" ? 1920 : 1350,
    story = channel === "story";
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d")!;
  const template = getPostTemplate(draft.template);
  const color = draft.color || template.color,
    accent = draft.accent || template.accent;
  const layout = template.layout,
    top = story ? 185 : 72,
    bottom = H - (story ? 180 : 66),
    usable = bottom - top;
  const items: Row[] =
    channel === "carousel" ? draft.items.slice(slide, slide + 1) : draft.items;
  if (!items.length)
    throw Error("Choose a dish photo before creating this design.");
  const images: ImageBitmap[] = [];
  const renderedText: string[] = [];
  const textBoxes: {
    value: string;
    x: number;
    y: number;
    width: number;
    height: number;
  }[] = [];
  const title = draft.title ?? items[0].name ?? "";
  const textMode = draft.textMode || template.textMode;
  const showBrand = draft.showBrand ?? template.showBrand;
  const kicker = draft.kicker ?? template.kicker,
    cta = draft.cta ?? template.cta;
  const price =
    draft.showPrice && draft.price !== "" && draft.price != null
      ? money(Math.round(Number(draft.price) * 100), restaurant.currency)
      : "";
  const offset = Math.max(-10, Math.min(10, Number(draft.textY || 0))) * 3;
  const itemNames = items
    .map(
      (i) =>
        (items.length > 1 || (i.quantity || 1) > 1 || channel === "carousel"
          ? (i.quantity || 1) + " × "
          : "") + i.name,
    )
    .join(" · ");
  const detailCopy = [title !== itemNames ? itemNames : "", draft.description]
    .filter(Boolean)
    .join("\n");
  function fill(c: string, x = 0, y = 0, w = W, h = H) {
    ctx.fillStyle = c;
    ctx.fillRect(x, y, w, h);
  }
  function round(
    x: number,
    y: number,
    w: number,
    h: number,
    r: number,
    c: string,
  ) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fillStyle = c;
    ctx.fill();
  }
  function text(
    value: string,
    x: number,
    y: number,
    w: number,
    h: number,
    size: number,
    c: string,
    options: {
      serif?: boolean;
      family?: "sans" | "serif" | "italic" | "condensed" | "hand";
      italic?: boolean;
      align?: "left" | "center" | "right";
      weight?: number;
    } = {},
  ) {
    if (!value?.trim()) return;
    const family =
      options.family ||
      (options.italic ? "italic" : options.serif ? "serif" : "sans");
    const font =
      draft.typography && draft.typography !== "template" && size >= 45
        ? `"${brandTypeface({ typography: draft.typography }).family}"`
        : '"' +
          {
            sans: "Post Sans",
            serif: "Post Serif",
            italic: "Post Italic",
            condensed: "Post Condensed",
            hand: "Post Hand",
          }[family] +
          '"';
    let lines: string[] = [],
      fs = size;
    const wrap = () => {
      lines = [];
      for (const paragraph of String(value).split("\n")) {
        let line = "";
        for (const word of paragraph.split(/\s+/)) {
          if (!word) continue;
          if (ctx.measureText(line ? line + " " + word : word).width <= w)
            line = line ? line + " " + word : word;
          else {
            if (line) lines.push(line);
            line = "";
            for (const char of word) {
              if (ctx.measureText(line + char).width > w) {
                lines.push(line);
                line = "";
              }
              line += char;
            }
          }
        }
        if (line) lines.push(line);
      }
    };
    for (; fs >= 18; fs--) {
      ctx.font =
        "" +
        (options.weight || (options.serif ? 400 : 700)) +
        " " +
        fs +
        "px " +
        font;
      wrap();
      if (lines.length * fs * 1.1 <= h) break;
    }
    if (fs < 18 || lines.length * fs * 1.1 > h + 2)
      throw Error(
        "Some text is too long for this design. Shorten the headline or details.",
      );
    ctx.fillStyle = c;
