export function photoPresetFields(id: string) {
  const preset = photoStyles.find((p) => p.id === id);
  if (!preset) throw Error("Choose an available photo style.");
  return {
    photoPreset: preset.id,
    photoStyle: preset.prompt,
    referenceIds: [],
    photoDefaults: {
      surface: "As shown",
      lighting: "As shown",
      plate: "style",
      angle: "keep",
      composition: "Full dish",
    },
  };
}

export function restaurantLookFields(id: string) {
  const look = restaurantLooks.find((l) => l.id === id);
  if (!look) throw Error("Choose an available restaurant look.");
  return {
    ...photoPresetFields(look.photoPreset),
    primary: look.primary,
    accent: look.accent,
    typography: look.typography,
    autoApply: true,
  };
}

export function normalizeBrandColor(value: string) {
  const hex = value.trim().replace(/^#/, "");
  if (/^[\da-f]{3}$/i.test(hex))
    return (
      "#" +
      [...hex]
        .map((c) => c + c)
        .join("")
        .toLowerCase()
    );
  return /^[\da-f]{6}$/i.test(hex) ? "#" + hex.toLowerCase() : null;
}

export function readableBrandInk(color: string) {
  const hex = normalizeBrandColor(color) || "#ffffff";
  const values = [1, 3, 5].map((i) => {
    const c = parseInt(hex.slice(i, i + 2), 16) / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  const luminance =
    values[0] * 0.2126 + values[1] * 0.7152 + values[2] * 0.0722;
  return luminance > 0.179 ? "#000000" : "#ffffff";
}
export function brandTypeface(style: Record<string, any> = {}) {
  return (
    brandTypefaces.find((font) => font.id === style.typography) ||
    brandTypefaces[0]
  );
}
export function restaurantPhotoDefaults(restaurant: Record<string, any>) {
  const style = restaurant.style || {};
  if (!style.autoApply) return {};
  return {
    look: "restaurant",
    styleChosen: true,
    photoStyleSnapshot: style.photoStyle || null,
    photoReferenceIds: style.referenceIds || null,
    lookCategory:
      photoStyles.find((p) => p.id === style.photoPreset)?.category || "menu",
    surface: style.photoDefaults?.surface || "As shown",
    lighting: style.photoDefaults?.lighting || "As shown",
    plate: style.photoDefaults?.plate || "style",
    angle: style.photoDefaults?.angle || "keep",
    composition: style.photoDefaults?.composition || "Full dish",
  };
}

const photoSelectionKeys = [
  "look",
  "lookCategory",
  "surface",
  "lighting",
  "plate",
  "angle",
  "composition",
  "photoStyleSnapshot",
  "photoReferenceIds",
] as const;

export function restaurantPhotoSelection(
  draft: Record<string, any>,
  restaurant: Record<string, any>,
  enabled: boolean,
) {
  const selection = (value: Record<string, any>) =>
    Object.fromEntries(
      photoSelectionKeys
        .filter((key) => value[key] !== undefined)
        .map((key) => [key, value[key]]),
    );
  if (enabled) {
    return {
      ...restaurantPhotoDefaults({
        style: { ...restaurant.style, autoApply: true },
      }),
      previousPhotoStyle:
        draft.look === "restaurant"
          ? draft.previousPhotoStyle || null
          : selection(draft),
    };
  }
  const previous = draft.previousPhotoStyle;
  const hasPrevious =
    previous &&
    (photoStyles.some((style) => style.id === previous.look) ||
      ["keep", "reference"].includes(previous.look));
  const fallback =
    photoStyles.find((style) => style.id === restaurant.style?.photoPreset) ||
    photoStyles.find((style) => style.id === "menu-stone")!;
  return {
    look: fallback.id,
    photoStyleSnapshot: null,
    photoReferenceIds: null,
    lookCategory: fallback.category,
    surface: "As shown",
    lighting: "As shown",
    plate: "style",
    angle: fallback.angle || "keep",
    composition: "Full dish",
    ...(hasPrevious ? selection(previous) : {}),
    styleChosen: true,
    previousPhotoStyle: null,
  };
}
export function brandPostFields(style: Record<string, any> = {}) {
  return {
    color: style.primary || "#202820",
    accent: style.accent || "#f0e3c3",
    typography: brandTypeface(style).id,
    brandMode: "restaurant",
  };
}
// Public menu data never needs the private photographic prompt or reference IDs.
export function publicBrandStyle(style: Record<string, any> = {}) {
  return {
    primary: /^#[0-9a-f]{6}$/i.test(style.primary) ? style.primary : "#202820",
    accent: /^#[0-9a-f]{6}$/i.test(style.accent) ? style.accent : "#f0e3c3",
    typography: brandTypeface(style).id,
  };
}

import { env } from "cloudflare:workers";
import { canonicalStudioEvents } from "../studio-events";
import {
  createHash,
  randomBytes,
  scryptSync,
  timingSafeEqual,
} from "node:crypto";
export type Row = Record<string, any>;
export function config(key: string, fallback = "") {
  return String((env as any)[key] ?? process.env[key] ?? fallback);
}
export function db() {
  if (!env.DB)
    throw new AppError(
      503,
      "The workspace database is unavailable. Please try again.",
    );
  return env.DB;
}
export function bucket() {
  if (!env.BUCKET)
    throw new AppError(503, "File storage is unavailable. Please try again.");
  return env.BUCKET;
}
export const now = () => Date.now();
export const id = () => crypto.randomUUID();
export const token = () => randomBytes(32).toString("base64url");
export const digest = (s: string) =>
  createHash("sha256").update(s).digest("hex");
export function hashPassword(p: string) {
  const salt = token();
  return salt + ":" + scryptSync(p, salt, 64).toString("hex");
}
export function checkPassword(p: string, hash: string) {
  const [salt, h] = hash.split(":");
  const expected = Buffer.from(h || "00".repeat(64), "hex");
  const actual = scryptSync(p, salt || "dummy", 64);
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}
export class AppError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}
export function assert(ok: any, status: number, message: string): asserts ok {
  if (!ok) throw new AppError(status, message);
}
export async function one(sql: string, ...args: any[]): Promise<Row | null> {
  return db()
    .prepare(sql)
    .bind(...args)
    .first<Row>();
}
export async function all(sql: string, ...args: any[]): Promise<Row[]> {
  return (
    await db()
      .prepare(sql)
      .bind(...args)
      .all<Row>()
  ).results;
}
export async function run(sql: string, ...args: any[]) {
  return db()
    .prepare(sql)
    .bind(...args)
    .run();
}
export async function event(
  restaurant: string | null,
  kind: string,
  entity: string | null = null,
  details: object = {},
  dedupeKey?: string,
) {
  await run(
    "INSERT INTO events (id,restaurant_id,kind,entity_id,details,created_at) VALUES (?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING",
    dedupeKey ? digest(`${restaurant}:${kind}:${entity}:${dedupeKey}`) : id(),
    restaurant,
    kind,
    entity,
    JSON.stringify({
      ...details,
      ...(canonicalStudioEvents[kind]
        ? { canonicalEvent: canonicalStudioEvents[kind] }
        : {}),
      measurementMode:
        config("LOCAL_DEVELOPMENT") === "true" ||
        config("STUDIO_INTERNAL_QA") === "true"
          ? "internal"
          : "production",
      eventSchema: 2,
    }),
    now(),
  );
}
export function response(
  body: unknown,
  status = 200,
  headers: HeadersInit = {},
) {
  return Response.json(body, {
    status,
    headers: {
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
      ...headers,
    },
  });
}
export async function body(req: Request) {
  assert(
    Number(req.headers.get("content-length") || 0) < 100000,
    413,
    "This request is too large.",
  );
  let v;
  try {
    const { limitedBytes } = await import("./safeguards");
    const text = new TextDecoder().decode(await limitedBytes(req, 99999));
    assert(text.length < 100000, 413, "This request is too large.");
    v = JSON.parse(text);
  } catch (e) {
    if (e instanceof AppError) throw e;
    throw new AppError(400, "Please check the form and try again.");
  }
  return v;
}
export function sameOrigin(req: Request) {
  const origin = req.headers.get("origin");
  assert(
    !origin || origin === new URL(req.url).origin,
    403,
    "Please submit from this site.",
  );
  assert(
    req.headers.get("sec-fetch-site") !== "cross-site",
    403,
    "Please submit from this site.",
  );
}
export async function limit(key: string, max = 20, seconds = 900) {
  const k = digest(key),
    t = now();
  const r = await one(
    "INSERT INTO rate_limits (key,count,expires_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN expires_at<? THEN 1 ELSE count+1 END,expires_at=CASE WHEN expires_at<? THEN excluded.expires_at ELSE expires_at END RETURNING count",
    k,
    t + seconds * 1000,
    t,
    t,
  );
  assert(
    r && r.count <= max,
    429,
    "Too many attempts. Please try again in a few minutes.",
  );
}
export async function viewer(req: Request) {
  const raw = req.headers
    .get("cookie")
    ?.split(";")
    .map((s) => s.trim())
    .find((s) => s.startsWith("dishlight_session="))
    ?.split("=")[1];
  if (!raw) return null;
  return one(
